INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('454b824c-cc1a-4846-97d8-7c036712895b'::uuid, 'card_description', 'Red cairn: that is what the name of this hill means. On the south side of a broad valley, the hill holds two Iron Age hillforts, known in English as the big fort and the little fort.', 'On the hill of Y Garn Goch, the red cairn, lie two impressive Iron Age hillforts, the big fort and the little fort: in the established view, together the largest in southern Wales.', 'teaser-card-s047-rollback:454b824c-cc1a-4846-97d8-7c036712895b:card_description', 'rollback of teaser-card-s047: card_description ''On the hill of Y Garn Goch, the red cairn, lie two impressive Iron Age hillforts, the big fort and the little fort: in the established view, together the largest in southern Wales.'' restored on Y Garn Goch', 'e48477c0dc90173a9e8f3fd9900520e4a2740f59d23fd8c825b372e81faa7a63|338f859ee51a72bc36c2c421bff15a43dc8f5b8105865c275abea656feb1e3d9|338f859ee51a72bc36c2c421bff15a43dc8f5b8105865c275abea656feb1e3d9', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Red cairn: that is what the name of this hill means. On the south side of a broad valley, the hill holds two Iron Age hillforts, known in English as the big fort and the little fort."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site''s name means red cairn [S2]; the site is a hill [S1]; the hill lies on the south side of a broad valley [S3]; the hill holds two Iron Age hillforts [S5]; in English the forts are called the big fort and the little fort [S5]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The hill (Y Garn Goch, Carmarthenshire, Wales) holds two hillforts known in English as the big fort and the little fort. [SUPPORTED: https://www.britainexpress.com/attractions.htm?attraction=4942]; The name of this hill means red cairn. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=5987]; The hill lies on the south side of a broad valley. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=5987]; The hill holds two hillforts. [SUPPORTED: https://coflein.gov.uk/en/sites/100866]; The two hillforts are Iron Age. [SUPPORTED: https://www.britainexpress.com/attractions.htm?attraction=4942]"}]'::jsonb),
    ('45a26f12-c56f-4ebb-bc65-ba9488b84826'::uuid, 'card_description', 'Channels cut into this rock pyramid may have drained liquids in animal sacrifices. Cut from one block of volcanic tuff, the pyramid is believed to have been an altar for diviners'' rituals.', '7th-6th century BC Etruscan altar carved from a single volcanic block, used by haruspices for divination. Surrounded by Etruscan inscriptions, tombs, medieval ruins, and a tower linked to Pasolini.', 'teaser-card-s047-rollback:45a26f12-c56f-4ebb-bc65-ba9488b84826:card_description', 'rollback of teaser-card-s047: card_description ''7th-6th century BC Etruscan altar carved from a single volcanic block, used by haruspices for divination. Surrounded by Etruscan inscriptions, tombs, medieval ruins, and a tower linked to Pasolini.'' restored on Etruscan Pyramid of Bomarzo', '94069a0a7f16af63832e26aff918fa838b44b10004b9a33ff9cb4e7781fd255b|6f324638324e2bb55be67d00f8dbd3c143edfec3b47955e49e183e8d6655913f|6f324638324e2bb55be67d00f8dbd3c143edfec3b47955e49e183e8d6655913f', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Channels cut into this rock pyramid may have drained liquids in animal sacrifices. Cut from one block of volcanic tuff, the pyramid is believed to have been an altar for diviners'' rituals."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "channels are cut into the rock of the monument [S3]; the channels may have drained liquids during animal sacrifices [S3]; the monument is a rock-cut pyramid [S1, S2]; it is cut from a single block [S1]; the block is volcanic tuff [S1]; the pyramid is believed to have served as an altar [S2]; the altar is believed to have been used for the rituals of diviners [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This monument is a rock pyramid [SUPPORTED: https://archeologiaepaesaggio.wordpress.com/2021/02/15/la-piramide-di-bomarzo/]; Channels are cut into this rock pyramid [SUPPORTED: https://archeologiaepaesaggio.wordpress.com/2021/02/15/la-piramide-di-bomarzo/]; The channels may have drained liquids [SUPPORTED: https://archeologiaepaesaggio.wordpress.com/2021/02/15/la-piramide-di-bomarzo/]; The liquids may have been drained in animal sacrifices [SUPPORTED: https://archeologiaepaesaggio.wordpress.com/2021/02/15/la-piramide-di-bomarzo/]; The pyramid is cut from one block [SUPPORTED: https://archeologiaepaesaggio.wordpress.com/2021/02/15/la-piramide-di-bomarzo/]; The block is volcanic tuff [SUPPORTED: https://archeologiaepaesaggio.wordpress.com/2021/02/15/la-piramide-di-bomarzo/]; The pyramid is believed to have been an altar [SUPPORTED: https://archeologiaepaesaggio.wordpress.com/2021/02/15/la-piramide-di-bomarzo/]; The altar is believed to have been for diviners'' rituals [SUPPORTED: https://irintronauti.altervista.org/la-piramide-etrusca-di-bomarzo/]"}]'::jsonb),
    ('49835383-20b8-44e0-9bf1-9e06cf2ecbb1'::uuid, 'card_description', 'A canal about 500 m long was dug across this island at its narrowest place. Clad in wooden linings, the canal could carry vessels with a draught of up to 1 m in its time.', 'In the Kattegat, Samsø was cut at its narrowest place by a canal about 500 m long, dug and clad with wooden linings in the years 726–729 AD. In the Viking Age it became a meeting place.', 'teaser-card-s047-rollback:49835383-20b8-44e0-9bf1-9e06cf2ecbb1:card_description', 'rollback of teaser-card-s047: card_description ''In the Kattegat, Samsø was cut at its narrowest place by a canal about 500 m long, dug and clad with wooden linings in the years 726–729 AD. In the Viking Age it became a meeting place.'' restored on Samsø', 'b07aed0c75b045ec86b899333aeca370f5bf5c21acd59f5fa00b31691f92f9e4|8a4cf4505acd1d81fa174fb9919716dfcef3fe4a2e9ade819b37145bead46064|8a4cf4505acd1d81fa174fb9919716dfcef3fe4a2e9ade819b37145bead46064', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A canal about 500 m long was dug across this island at its narrowest place. Clad in wooden linings, the canal could carry vessels with a draught of up to 1 m in its time."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a canal was dug across the island [S5]; it was dug at the island''s narrowest place [S5]; the canal was about 500 m long [S6]; the canal was clad with wooden linings [S7]; in its time it could carry vessels with a draught of up to 1 m [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A canal was dug across this island (Samsø) [SUPPORTED: https://www.vikingeskibsmuseet.dk/fagligt/e-laering/viden-om-vikingetiden/vikingetidens-geografi/runesten-og-billedsten/spor-efter-vikingerne/kanhavekanalen]; The canal was about 500 m long [SUPPORTED: https://fortidsmindeguide.dk/index.php?id=263&no_html=1&option=com_osproperty&task=property_pdf]; The canal was dug at the island''s narrowest place [SUPPORTED: https://da.wikipedia.org/wiki/Kanhavekanalen]; The canal was clad in wooden linings [SUPPORTED: https://www.vikingeskibsmuseet.dk/fagligt/e-laering/viden-om-vikingetiden/vikingetidens-geografi/runesten-og-billedsten/spor-efter-vikingerne/kanhavekanalen]; In its time the canal could carry vessels with a draught of up to 1 m [SUPPORTED: https://da.wikipedia.org/wiki/Kanhavekanalen]"}]'::jsonb),
    ('4dc7086c-f261-4f38-85f2-10a20eeda1bc'::uuid, 'card_description', 'A rockslide sealed the original entrance and kept the cave floor pristine. That floor is one of the best preserved from the Paleolithic, with more than 4,000 fossils.', 'At La Garma Cave Complex, a rockslide sealed the original entrance about 16,000 years ago, keeping a Paleolithic floor pristine: more than 4,000 fossils, and an ibex carved on a bovine rib.', 'teaser-card-s047-rollback:4dc7086c-f261-4f38-85f2-10a20eeda1bc:card_description', 'rollback of teaser-card-s047: card_description ''At La Garma Cave Complex, a rockslide sealed the original entrance about 16,000 years ago, keeping a Paleolithic floor pristine: more than 4,000 fossils, and an ibex carved on a bovine rib.'' restored on La Garma Cave Complex', '2310e912f3008e04c62bebc0b9b2ffa2d17b40ed01b8eacac836d554c207bfc3|5f1ee34d92da9f7f5805bb058f94ae751a812d103aebc5333552d7b696220202|5f1ee34d92da9f7f5805bb058f94ae751a812d103aebc5333552d7b696220202', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A rockslide sealed the original entrance and kept the cave floor pristine. That floor is one of the best preserved from the Paleolithic, with more than 4,000 fossils."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a rockslide sealed the cave''s original entrance [S5]; this kept the cave floor pristine [S5]; the floor is one of the best preserved from the Paleolithic [S2]; it holds more than 4,000 fossils [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A rockslide sealed the original entrance of this cave (La Garma, Lower Gallery) [SUPPORTED: https://www.arterupestrecantabrico.es/en/cuevas/cueva-de-la-garma.html]; The sealing kept the cave floor pristine [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0163591]; That floor is one of the best preserved from the Paleolithic [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0163591]; The floor holds more than 4,000 fossils [SUPPORTED: https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0163591]"}]'::jsonb),
    ('50cbcf03-2e37-4f82-9705-a55c9264b3d5'::uuid, 'card_description', 'Bones of the dead here were dated by radiocarbon and run through one model. It suggests the site came into use in 2875-2700 BC; its objects now rest in a museum.', 'Radiocarbon dates on human bone suggest use of the Tholos de Montelirio began in 2875–2700 BC. The site is closed to the public, but its objects wait in the Archeological Museum of Seville.', 'teaser-card-s047-rollback:50cbcf03-2e37-4f82-9705-a55c9264b3d5:card_description', 'rollback of teaser-card-s047: card_description ''Radiocarbon dates on human bone suggest use of the Tholos de Montelirio began in 2875–2700 BC. The site is closed to the public, but its objects wait in the Archeological Museum of Seville.'' restored on Tholos de Montelirio', 'bbfcd600181927a9e24049b2ffa575adff9f9803d8a35421ac9866bfd651352d|10054478ceecb59595a48fcc2a6bdc2cb86d4e9cd93bdd7288f2d03551d6adbc|10054478ceecb59595a48fcc2a6bdc2cb86d4e9cd93bdd7288f2d03551d6adbc', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Bones of the dead here were dated by radiocarbon and run through one model. It suggests the site came into use in 2875-2700 BC; its objects now rest in a museum."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "human bones from the site were radiocarbon dated [S3]; the dates were run through a model [S3]; the model suggests the site''s use started in 2875-2700 BC [S3]; the site''s objects are now in a museum [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Bones of the dead at this site (Tholos de Montelirio) were dated by radiocarbon [SUPPORTED: https://link.springer.com/article/10.1007/s10963-018-9114-2]; The radiocarbon dates were run through one model [SUPPORTED: https://link.springer.com/article/10.1007/s10963-018-9114-2]; The model suggests the site came into use in 2875-2700 BC [SUPPORTED: https://link.springer.com/article/10.1007/s10963-018-9114-2]; The site''s objects now rest in a museum [SUPPORTED: https://ceres.mcu.es/pages/ResultSearch?txtSimpleSearch=Tholos+de+Montelirio&simpleSearch=0&hipertextSearch=1&search=simple&MuseumsRolSearch=1&listaMuseos=null]"}]'::jsonb),
    ('54bbe431-e520-498c-8413-4bbc23eb4947'::uuid, 'card_description', 'Stone monoliths carved in human form join a pyramidal hill with sandstone walls. The local community considers the site a sacred ceremonial center, with Pachamama offerings at carnival.', 'Inca-era site between Chucuito and Puno on the Lake Titicaca shore, declared National Cultural Heritage. The lakeside position linked it to the sacred geography and ritual landscape of Titicaca.', 'teaser-card-s047-rollback:54bbe431-e520-498c-8413-4bbc23eb4947:card_description', 'rollback of teaser-card-s047: card_description ''Inca-era site between Chucuito and Puno on the Lake Titicaca shore, declared National Cultural Heritage. The lakeside position linked it to the sacred geography and ritual landscape of Titicaca.'' restored on Inka Tunuwiri', 'efd29a2a1b37a69340848db0505699907e21c95057da68ed82734e64f7787795|485979486b9273a795150b83ac27eab3e0917bffe18624ccca598197895a6ba4|485979486b9273a795150b83ac27eab3e0917bffe18624ccca598197895a6ba4', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Stone monoliths carved in human form join a pyramidal hill with sandstone walls. The local community considers the site a sacred ceremonial center, with Pachamama offerings at carnival."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site has stone monoliths carved in human form [S2]; it has a pyramidal hill [S2]; the hill has sandstone walls [S2]; the local community considers the site a sacred ceremonial center [S4]; Pachamama offerings are made there at carnival [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Stone monoliths carved in human form stand here (Inka Tunuwiri) [SUPPORTED: https://elcomercio.pe/vamos/peru/el-enigmatico-centro-ceremonial-que-puno-quiere-dar-a-conocer-al-mundo-puno-ichu-noticia/]; The monoliths join a pyramidal hill [SUPPORTED: https://elcomercio.pe/vamos/peru/el-enigmatico-centro-ceremonial-que-puno-quiere-dar-a-conocer-al-mundo-puno-ichu-noticia/]; The site has sandstone walls [SUPPORTED: https://colturperu.com/blog/puno-mas-alla-del-lago-titicaca/]; The local community considers the site sacred [SUPPORTED: https://titicacayachtadventures.com/centro-ceremonial-inca-tunuhuiri/]; The site is a ceremonial center [SUPPORTED: https://colturperu.com/blog/puno-mas-alla-del-lago-titicaca/]; Pachamama offerings are made at the site at carnival [SUPPORTED: https://elcomercio.pe/vamos/peru/el-enigmatico-centro-ceremonial-que-puno-quiere-dar-a-conocer-al-mundo-puno-ichu-noticia/]"}]'::jsonb),
    ('556ae8b8-dacf-4bad-ba3a-5b05551f1f99'::uuid, 'card_description', 'Only two of the original columns remained standing here. This was the fourth largest Ionic temple of the ancient world, about 44.6 by 97.6 metres, with eight columns on each end.', '3rd century BC–4th century AD — the fourth largest Ionic temple in the world at Sardis. A massive archaic limestone altar at the west end predates the temple, hinting sacred to Artemis far earlier.', 'teaser-card-s047-rollback:556ae8b8-dacf-4bad-ba3a-5b05551f1f99:card_description', 'rollback of teaser-card-s047: card_description ''3rd century BC–4th century AD — the fourth largest Ionic temple in the world at Sardis. A massive archaic limestone altar at the west end predates the temple, hinting sacred to Artemis far earlier.'' restored on Temple of Artemis - Sardes', 'd04b3ba9be5104621120fa78a4db7099df0a052f698a2c8b5cb2c76ab7a123eb|f6d7a435b4469c00165a7a4d732e08a9ce2a0629121d35b1842037b2bb57b4e3|f6d7a435b4469c00165a7a4d732e08a9ce2a0629121d35b1842037b2bb57b4e3', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Only two of the original columns remained standing here. This was the fourth largest Ionic temple of the ancient world, about 44.6 by 97.6 metres, with eight columns on each end."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "only two of the original columns remained standing [S4]; it was the fourth largest Ionic temple of the ancient world [S1]; it measures about 44.6 by 97.6 metres [S3]; it had eight columns on each end [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Only two of the original columns remained standing here (Temple of Artemis, Sardis) [SUPPORTED: https://sardisexpedition.org/en/essays/r7-yegul-ch1-introduction]; This was the fourth largest Ionic temple of the ancient world [SUPPORTED: https://sardisexpedition.org/en/essays/r7-yegul-ch1-introduction]; The temple measures about 44.6 by 97.6 metres [SUPPORTED: https://sardisexpedition.org/en/essays/r7-yegul-ch1-introduction]; The temple had eight columns on each end [SUPPORTED: https://sardisexpedition.org/en/essays/r7-yegul-ch1-introduction]"}]'::jsonb),
    ('563693f3-5fa9-485d-940f-66f26210a9f4'::uuid, 'card_description', 'A moaning animal led its herdsman to a sea teeming with tuna, Pausanias says. After an enormous catch, the people paid for this bronze statue at Apollo''s sanctuary with a tithe.', 'A bronze bull dedicated at Delphi to commemorate an exceptional tuna fish catch. The citizens of Corfu considered the haul so miraculous it warranted a monument to Apollo.', 'teaser-card-s047-rollback:563693f3-5fa9-485d-940f-66f26210a9f4:card_description', 'rollback of teaser-card-s047: card_description ''A bronze bull dedicated at Delphi to commemorate an exceptional tuna fish catch. The citizens of Corfu considered the haul so miraculous it warranted a monument to Apollo.'' restored on Bull of the Corcyreans', 'e7469f0cb120cbf1ae8ee266f74607ae7a5301247fd462d88467e4872badb81c|f779ebff03c33cfa02708d99c5826b3ed4b0e98f22cd7fcc716ec82de08ce1ee|f779ebff03c33cfa02708d99c5826b3ed4b0e98f22cd7fcc716ec82de08ce1ee', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A moaning animal led its herdsman to a sea teeming with tuna, Pausanias says. After an enormous catch, the people paid for this bronze statue at Apollo''s sanctuary with a tithe."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "according to Pausanias, a moaning animal (the bull) went to the shore [S2]; the herdsman, following it, found the sea teeming with tuna [S2]; an enormous catch followed [S3]; the people paid for the statue with a tithe of the proceeds [S3]; the statue was bronze [S1]; it stood at Apollo''s sanctuary [S1]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This is a bronze statue (the bronze bull dedicated by the Corcyreans) [SUPPORTED: https://www.theoi.com/Text/Pausanias10A.html]; The statue stands at Apollo''s sanctuary [SUPPORTED: https://wordpressua.uark.edu/dlevine/daniel-b-levine-tuna-lecture-copywrite-2011/]; A moaning animal (a bull) [SUPPORTED: https://www.theoi.com/Text/Pausanias10A.html]; The animal led its herdsman to the sea [SUPPORTED: https://www.theoi.com/Text/Pausanias10A.html]; The sea was teeming with tuna [SUPPORTED: https://www.theoi.com/Text/Pausanias10A.html]; Pausanias says so [SUPPORTED: https://wordpressua.uark.edu/dlevine/daniel-b-levine-tuna-lecture-copywrite-2011/]; There was an enormous catch [SUPPORTED: https://en.wikipedia.org/wiki/Pausanias%27_description_of_Delphi]; The people paid for this bronze statue with a tithe [SUPPORTED: https://www.theoi.com/Text/Pausanias10A.html]"}]'::jsonb),
    ('5699564f-61e7-481d-99dc-d23edc32207b'::uuid, 'card_description', 'Three ballcourts lie in this Zapotec elite complex, the largest 45 by 22 metres. Digs uncovered effigy vessels and funerary urns that show advanced Zapotec craft.', 'Occupied 650–850 AD on a hilltop above Monte Albán, this satellite city supplied quarried stone to the larger centre below and produced the green-glazed pottery traded as far as Teotihuacan.', 'teaser-card-s047-rollback:5699564f-61e7-481d-99dc-d23edc32207b:card_description', 'rollback of teaser-card-s047: card_description ''Occupied 650–850 AD on a hilltop above Monte Albán, this satellite city supplied quarried stone to the larger centre below and produced the green-glazed pottery traded as far as Teotihuacan.'' restored on Atzompa', '7c6e812e31a60dfe64d8861f5e6424139eac47531c76d3d5d5ec38ede20f1fd2|69dde45ce27a690deb6e1d17c22657bddfeed8c5596bbd8b61b9edab48ef0cf8|69dde45ce27a690deb6e1d17c22657bddfeed8c5596bbd8b61b9edab48ef0cf8', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Three ballcourts lie in this Zapotec elite complex, the largest 45 by 22 metres. Digs uncovered effigy vessels and funerary urns that show advanced Zapotec craft."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-008 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there are three ballcourts [S2]; the site is a Zapotec elite complex [S1]; the largest ballcourt measures 45 by 22 metres [S2]; excavations uncovered effigy vessels [S3]; excavations uncovered funerary urns [S3]; these show advanced Zapotec craftsmanship [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Three ballcourts lie in this complex (Atzompa) [SUPPORTED: https://lugares.inah.gob.mx/en/node/4501]; The largest ballcourt measures 45 by 22 metres [SUPPORTED: https://lugares.inah.gob.mx/en/node/4501]; It is a Zapotec complex [SUPPORTED: https://lugares.inah.gob.mx/en/node/4501]; It is an elite complex [SUPPORTED: https://lugares.inah.gob.mx/en/node/4501]; Digs uncovered effigy vessels [SUPPORTED: https://inah.gob.mx/foto-del-dia/la-senora-agua-vasija]; Digs uncovered funerary urns [SUPPORTED: https://revistas.inah.gob.mx/index.php/arqueologia/article/view/6168]; The vessels and urns show advanced Zapotec craft [SUPPORTED: https://revistas.inah.gob.mx/index.php/arqueologia/article/view/6168]"}]'::jsonb),
    ('57e9b3c3-1d32-49dd-ad8c-49577ed78d06'::uuid, 'card_description', 'Clay pipes in this ruined castle''s walls may show water came from outside in wartime. The castle''s foundations are thought to be Roman, and tunnels led to exits several km from the city.', 'From Peqin Castle, tunnels led to exits several km from the city, and clay pipes in its walls suggest water was supplied from outside in wartime. Its last resident was Demir Pasha.', 'teaser-card-s047-rollback:57e9b3c3-1d32-49dd-ad8c-49577ed78d06:card_description', 'rollback of teaser-card-s047: card_description ''From Peqin Castle, tunnels led to exits several km from the city, and clay pipes in its walls suggest water was supplied from outside in wartime. Its last resident was Demir Pasha.'' restored on Peqin Castle', 'ad7efaa975c4a25b76e3acaf8792c4af4ba8abc915df628cef3ae0e381be7a2e|47935f0017d6d8011eab3cbe5dce34a5008f08f5a79a65fe32b389dddd170809|47935f0017d6d8011eab3cbe5dce34a5008f08f5a79a65fe32b389dddd170809', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Clay pipes in this ruined castle''s walls may show water came from outside in wartime. The castle''s foundations are thought to be Roman, and tunnels led to exits several km from the city."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "clay pipes were found in the castle''s walls [S7]; the castle is ruined [S1]; the pipes may indicate that water was supplied from outside during wartime (hedged) [S7]; the castle''s foundations are thought to be Roman [S2]; the castle had tunnels [S6]; the tunnels served as exits several km from the city [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Clay pipes have been found in this castle''s walls (Peqin Castle, Albania). [SUPPORTED: https://peqini.gov.al/historiku-i-qytetit/]; The clay pipes may show that water came from outside in wartime. [SUPPORTED: https://peqini.gov.al/historiku-i-qytetit/]; The castle is ruined. [SUPPORTED: https://akt.gov.al/en/atraksionet/kalaja-e-peqinit/]; The castle''s foundations are thought to be Roman. [SUPPORTED: https://peqini.gov.al/historiku-i-qytetit/]; The castle had tunnels that led to exits. [SUPPORTED: https://akt.gov.al/en/atraksionet/kalaja-e-peqinit/]; The tunnels'' exits lay several km from the city. [SUPPORTED: https://peqini.gov.al/atraksione-turistike/]"}]'::jsonb),
    ('58b67d2b-fb58-41b0-b7d3-16c36ca4507a'::uuid, 'card_description', 'Fire from heaven consumed a tyrant king and his castle, so a later legend goes. It says he probably lived on this peak, where a hillfort of roughly 25 acres has a spring near its centre.', 'On the peak of Foel Fenlli, ramparts enclose a hillfort with hut platforms and a spring. Legend says king Benlli probably lived here, till fire from heaven consumed him and his castle.', 'teaser-card-s047-rollback:58b67d2b-fb58-41b0-b7d3-16c36ca4507a:card_description', 'rollback of teaser-card-s047: card_description ''On the peak of Foel Fenlli, ramparts enclose a hillfort with hut platforms and a spring. Legend says king Benlli probably lived here, till fire from heaven consumed him and his castle.'' restored on Foel Fenlli', '60bcf5885d0b8ba804f2ea11616c55d86a7e87156a0fb85d4d1ee2c02946f648|de073b65d6f3290242a4edb911526370bb42642a4276b31ce8974701f32fac58|de073b65d6f3290242a4edb911526370bb42642a4276b31ce8974701f32fac58', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Fire from heaven consumed a tyrant king and his castle, so a later legend goes. It says he probably lived on this peak, where a hillfort of roughly 25 acres has a spring near its centre."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "according to a later legend, fire from heaven consumed a king and his castle [S4, S5]; the legend calls the king a tyrant [S4]; the legend says he probably lived on this peak [S4]; a hillfort lies on the peak [S3]; the hillfort is roughly 25 acres [S3]; the hillfort has a spring near its centre [S7]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "On this peak (Foel Fenlli, Wales) is a hillfort of roughly 25 acres. [SUPPORTED: https://coflein.gov.uk/en/site/96522/]; The hillfort has a spring near its centre. [SUPPORTED: https://www.clwydianrangeanddeevalleyaonb.org.uk/article/moel-fenlli/]; A legend goes that fire from heaven consumed a king. [SUPPORTED: https://sourcebooks.fordham.edu/basis/nennius-full.asp]; The king of the legend was a tyrant. [SUPPORTED: https://sourcebooks.fordham.edu/basis/nennius-full.asp]; In the legend the fire from heaven also consumed his castle. [SUPPORTED: https://sourcebooks.fordham.edu/basis/nennius-full.asp]; The legend is a later one (recorded long after the hillfort was built). [SUPPORTED: https://en.wikipedia.org/wiki/Benlli]; The legend says the king probably lived on this peak. [SUPPORTED: https://en.wikipedia.org/wiki/Benlli]"}]'::jsonb),
    ('5a440726-598a-48a2-87fc-ae833a534da6'::uuid, 'card_description', 'Woolly rhinoceros, hyena, wolf and lion remains turn up here, less often than horse. Mammoth remains made this settlement famous, now the biggest open-air one of its time in western Eurasia.', 'Mammoth, horse and reindeer remains lie at Breitenbach, currently the biggest open-air settlement in western Eurasia from the time anatomically modern humans first colonized Europe.', 'teaser-card-s047-rollback:5a440726-598a-48a2-87fc-ae833a534da6:card_description', 'rollback of teaser-card-s047: card_description ''Mammoth, horse and reindeer remains lie at Breitenbach, currently the biggest open-air settlement in western Eurasia from the time anatomically modern humans first colonized Europe.'' restored on Breitenbach - Archaeological Site', '64f75d5fdd3dcb5d4585a36613f1cd3005f16e34119e1f8b9b3491661c69f587|8953d24dead7acedb6136563ba215ef689d708ddbf3a12028e2232b1ab155d6b|8953d24dead7acedb6136563ba215ef689d708ddbf3a12028e2232b1ab155d6b', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Woolly rhinoceros, hyena, wolf and lion remains turn up here, less often than horse. Mammoth remains made this settlement famous, now the biggest open-air one of its time in western Eurasia."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "remains of woolly rhinoceros occur at the site [S8]; remains of hyena occur [S8]; remains of wolf occur [S8]; remains of lion occur [S8]; these occur to a lesser extent than horse remains [S8]; the site is known chiefly for its mammoth remains [S7]; it is a settlement [S1]; it is currently the biggest open-air settlement of its time period in western Eurasia [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Mammoth remains made this settlement famous (Breitenbach, Germany). [SUPPORTED: https://de.wikipedia.org/wiki/Fundplatz_Breitenbach]; Woolly rhinoceros remains turn up here. [SUPPORTED: https://de.wikipedia.org/wiki/Fundplatz_Breitenbach]; Hyena remains turn up here. [SUPPORTED: https://de.wikipedia.org/wiki/Fundplatz_Breitenbach]; Wolf remains turn up here. [SUPPORTED: https://de.wikipedia.org/wiki/Fundplatz_Breitenbach]; Lion remains turn up here. [SUPPORTED: https://de.wikipedia.org/wiki/Fundplatz_Breitenbach]; Woolly rhinoceros, hyena, wolf and lion remains turn up less often than horse. [SUPPORTED: https://de.wikipedia.org/wiki/Fundplatz_Breitenbach]; It is an open-air settlement. [SUPPORTED: https://www.lda-lsa.de/presse-und-oeffentlichkeitsarbeit/presseinformationen/201026-breitenbach]; It is now the biggest open-air settlement of its time (the Aurignacian) in western Eurasia. [SUPPORTED: https://www.lda-lsa.de/presse-und-oeffentlichkeitsarbeit/presseinformationen/201026-breitenbach]"}]'::jsonb),
    ('5a4f7d76-c0d1-45ba-9e61-4c1fab2eff51'::uuid, 'card_description', 'Shooting butts have destroyed part of this ring of stones on a moor. Twenty stones survive in an almost perfect circle, described as a cairn circle, a ring cairn enclosure or a stone circle.', 'On Burley Moor, twenty surviving stones set inside a low bank form Grubstones, an almost perfect circle about 10 metres across. Cairn circle, ring cairn or stone circle?', 'teaser-card-s047-rollback:5a4f7d76-c0d1-45ba-9e61-4c1fab2eff51:card_description', 'rollback of teaser-card-s047: card_description ''On Burley Moor, twenty surviving stones set inside a low bank form Grubstones, an almost perfect circle about 10 metres across. Cairn circle, ring cairn or stone circle?'' restored on Grubstones', '0ca3775735f2b4f3308dd6777098ed1a2986195ba7044017620e3bac79ec303a|b28842b17fd64e50abf3814186ed2361dbb9844d614b87f73da4f8ac0f13241f|b28842b17fd64e50abf3814186ed2361dbb9844d614b87f73da4f8ac0f13241f', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Shooting butts have destroyed part of this ring of stones on a moor. Twenty stones survive in an almost perfect circle, described as a cairn circle, a ring cairn enclosure or a stone circle."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "shooting butts have destroyed part of the circle [S7]; the site is a ring of stones [S4, S6]; it stands on a moor [S1]; twenty stones survive [S4]; the circle is almost perfectly circular [S4]; it has been described as a cairn circle [S6]; it has been described as a ring cairn enclosure [S6]; it has been described as a stone circle [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Shooting butts have destroyed part of this ring of stones [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=2211]; The site is a ring of stones [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=2211]; The ring of stones is on a moor [SUPPORTED: http://www.stone-circles.org.uk/stone/grubstones.htm]; Twenty stones survive [SUPPORTED: http://www.stone-circles.org.uk/stone/grubstones.htm]; The stones stand in an almost perfect circle [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=2211]; It has been described as a cairn circle [SUPPORTED: https://www.thenorthernantiquarian.org/2009/01/03/roms-law/]; It has been described as a ring cairn enclosure [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=2211]; It has been described as a stone circle [SUPPORTED: http://www.stone-circles.org.uk/stone/grubstones.htm]"}]'::jsonb),
    ('5d64e4f8-8a98-4cf7-a97b-c353d6029e84'::uuid, 'card_description', 'A coin hoard and human remains were buried around this long barrow in Roman times. The mound probably dates from the fourth millennium BCE, and a hearth was later set in the ditch around it.', 'Also called The Giant''s Grave, Julliberrie''s Grave is a long barrow near Chilham, probably raised in the fourth millennium BCE. A Romano-British coin hoard was later buried at its edge.', 'teaser-card-s047-rollback:5d64e4f8-8a98-4cf7-a97b-c353d6029e84:card_description', 'rollback of teaser-card-s047: card_description "Also called The Giant''s Grave, Julliberrie''s Grave is a long barrow near Chilham, probably raised in the fourth millennium BCE. A Romano-British coin hoard was later buried at its edge." restored on Julliberrie''s Grave', '07de8b2632256f089ce866d26d38b32a84a3649c401b402273864c64886d47ba|69571a4eb52ac3a67099d581a4ec3e65208b730ad825e13b4d7d3affc0cd8bba|69571a4eb52ac3a67099d581a4ec3e65208b730ad825e13b4d7d3affc0cd8bba', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A coin hoard and human remains were buried around this long barrow in Roman times. The mound probably dates from the fourth millennium BCE, and a hearth was later set in the ditch around it."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a coin hoard was buried around the barrow [S6]; human remains were buried around the barrow [S6]; these burials date to the Romano-British period [S6]; it is a long barrow [S1]; the mound probably dates from the fourth millennium BCE [S2]; a hearth was set in the ditch circling the barrow [S6]; the hearth came later than the mound''s construction [S2, S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A coin hoard was buried around this long barrow [SUPPORTED: https://heritage.kent.gov.uk/Monument/MKE4034/]; The coin hoard was buried in Roman times [SUPPORTED: https://heritage.kent.gov.uk/Monument/MKE4034/]; Human remains were buried around this long barrow in Roman times [SUPPORTED: https://heritage.kent.gov.uk/Monument/MKE4034/]; The site is a long barrow [SUPPORTED: https://heritage.kent.gov.uk/Monument/MKE4034/]; The mound probably dates from the fourth millennium BCE [SUPPORTED: https://heritage.kent.gov.uk/Monument/MKE4034/]; A ditch runs around the mound [SUPPORTED: https://heritage.kent.gov.uk/Monument/MKE4034/]; A hearth was later set in the ditch around it [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('5f9bc540-443e-41d6-93af-9c65dd28673b'::uuid, 'card_description', 'Over 80 adult men and women are believed to have been buried in this stone tomb. Looting hastened the first digs, which turned up flint arrowheads, bell-shaped pots and idols.', 'Six limestone slabs remain of the Anta de Carcavelos, a Chalcolithic communal grave. Over 80 adults are believed buried here, and flint arrowheads and cylindrical idols were found.', 'teaser-card-s047-rollback:5f9bc540-443e-41d6-93af-9c65dd28673b:card_description', 'rollback of teaser-card-s047: card_description ''Six limestone slabs remain of the Anta de Carcavelos, a Chalcolithic communal grave. Over 80 adults are believed buried here, and flint arrowheads and cylindrical idols were found.'' restored on Anta de Carcavelos', 'aa5d28d6389d82423e69a5047a28dcf12b713765bdd851141a47cf8ba35f7785|cd01977a3fd2797de3190a373bbf0413ccdc54c7c4c48ba0b4ce2afcb9eaa3a6|cd01977a3fd2797de3190a373bbf0413ccdc54c7c4c48ba0b4ce2afcb9eaa3a6', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Over 80 adult men and women are believed to have been buried in this stone tomb. Looting hastened the first digs, which turned up flint arrowheads, bell-shaped pots and idols."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-009 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "over 80 adults are believed to have been buried there [S5]; they were men and women [S5]; it is a stone tomb [S1, S2]; looting hastened the first excavations [S4]; the excavations found flint arrowheads [S6]; they found bell-shaped ceramics [S6]; they found idols [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wa