    ('67bb2bbe-a409-498b-acae-b1fa0e389cf4'::uuid, 'card_description', 'A bronze bowl plated with silver was among the finds at this Roman villa. The villa lies between two streams on a slope, and it began as a corridor villa before a wall joined its two wings.', 'Between two streams near Winchcombe, Spoonley Wood Roman Villa grew from a corridor villa into a courtyard villa. Its finds: a silver-plated bronze bowl and many 3rd- and 4th-century coins.', 'teaser-card-s047-rollback:67bb2bbe-a409-498b-acae-b1fa0e389cf4:card_description', 'rollback of teaser-card-s047: card_description ''Between two streams near Winchcombe, Spoonley Wood Roman Villa grew from a corridor villa into a courtyard villa. Its finds: a silver-plated bronze bowl and many 3rd- and 4th-century coins.'' restored on Spoonley Wood Roman Villa', '9ccd926adb70b207fce9801528ef91f935f88b0584ca42275f70a821587425cd|00a14c531136598714c56e415b8abe70f51cb4147054dcc803319896bc29c1e6|00a14c531136598714c56e415b8abe70f51cb4147054dcc803319896bc29c1e6', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A bronze bowl plated with silver was among the finds at this Roman villa. The villa lies between two streams on a slope, and it began as a corridor villa before a wall joined its two wings."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a silver-plated bronze bowl was among the finds [S8]; the site is a Roman villa [S1]; the villa lies between two streams [S3]; the villa lies on a slope [S3]; it began as a corridor villa [S5]; it had two wings [S5]; a wall later joined the two wings [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A bronze bowl plated with silver was among the finds at this Roman villa. [SUPPORTED: https://www.british-history.ac.uk/rchme/ancient-glos/pp112-115]; The site is a Roman villa. [SUPPORTED: https://www.british-history.ac.uk/rchme/ancient-glos/pp112-115]; The villa lies between two streams. [SUPPORTED: https://www.british-history.ac.uk/rchme/ancient-glos/pp112-115]; The villa lies on a slope. [SUPPORTED: https://www.british-history.ac.uk/rchme/ancient-glos/pp112-115]; The villa began as a corridor villa. [SUPPORTED: https://www.britainexpress.com/counties/glouces/roman/spoonley-wood.htm]; The villa had two wings. [SUPPORTED: https://www.roman-britain.co.uk/places/spoonley_wood/]; Later a wall joined the villa''s two wings. [SUPPORTED: https://www.roman-britain.co.uk/places/spoonley_wood/]"}]'::jsonb),
    ('695ecfa5-bd4e-4e81-9a5c-8251127d724e'::uuid, 'card_description', 'Large caves lie beneath the western entrance of this fortress. A deep ditch carved directly into rock surrounds it on all four sides, and its walls are of white cut stone.', '2nd-century AD Roman castle reused by Byzantines, Arabs, and Akkoyunlus, built on a rocky limestone hill. All four sides ringed by a rock-cut defence ditch, with caves underneath.', 'teaser-card-s047-rollback:695ecfa5-bd4e-4e81-9a5c-8251127d724e:card_description', 'rollback of teaser-card-s047: card_description ''2nd-century AD Roman castle reused by Byzantines, Arabs, and Akkoyunlus, built on a rocky limestone hill. All four sides ringed by a rock-cut defence ditch, with caves underneath.'' restored on Çimdin Kalesi', 'b32f6b312890f11a67fb11e6814b17ff1350cc844589d68f9c5d236c1e156c7e|15b67d285fd6ce613c372d24a8ef36caa44d1c944d00da1842133e2cd9860f45|15b67d285fd6ce613c372d24a8ef36caa44d1c944d00da1842133e2cd9860f45', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Large caves lie beneath the western entrance of this fortress. A deep ditch carved directly into rock surrounds it on all four sides, and its walls are of white cut stone."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a fortress [S1]; large caves lie beneath the western entrance [S3]; a deep ditch surrounds it on all four sides [S3]; the ditch is carved directly into rock [S3]; its walls are of white cut stone [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Large caves lie beneath the (western) entrance of this fortress. [SUPPORTED: https://artigercek.com/guncel/tarihi-cemdin-kalesi-ahira-donusturuldu-206166h]; The fortress''s entrance is on its western side. [SUPPORTED: https://dergipark.org.tr/tr/download/article-file/4351067]; A ditch surrounds the fortress on all four sides. [SUPPORTED: https://dergipark.org.tr/tr/download/article-file/4351067]; The ditch is carved directly into rock. [SUPPORTED: https://dergipark.org.tr/tr/download/article-file/4351067]; The ditch is deep. [SUPPORTED: https://dergipark.org.tr/tr/download/article-file/4351067]; Its walls are of white cut stone. [SUPPORTED: https://www.viransehir.gov.tr/cemdin-kalesi]"}]'::jsonb),
    ('69e786d2-00e3-4872-af8f-031fa6201248'::uuid, 'card_description', 'Timber huts stood on cleared bedrock in this Iron Age hillfort. The substantial huts were wattle and daub, and a single rampart with dry stone walls enclosed the triangular hilltop.', 'Flat-topped hill rising 191 m above the Avon, defended 300–100 BC and showing evidence of burning from a violent attack. It is among the proposed locations of the Battle of Badon.', 'teaser-card-s047-rollback:69e786d2-00e3-4872-af8f-031fa6201248:card_description', 'rollback of teaser-card-s047: card_description ''Flat-topped hill rising 191 m above the Avon, defended 300–100 BC and showing evidence of burning from a violent attack. It is among the proposed locations of the Battle of Badon.'' restored on Solsbury Hill', '2e55b77e1f00c92460e96ac532e280f21677759e07f11ed79f4b311e8861b35d|99a36ce79a09317ab3124408d3abdcba9b9e9e2ea6e8a969e0992a2e15ba4b94|99a36ce79a09317ab3124408d3abdcba9b9e9e2ea6e8a969e0992a2e15ba4b94', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Timber huts stood on cleared bedrock in this Iron Age hillfort. The substantial huts were wattle and daub, and a single rampart with dry stone walls enclosed the triangular hilltop."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-005 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "timber huts stood at the site [S2]; the huts were built on cleared bedrock [S2]; the site is an Iron Age hillfort [S1]; the huts were substantial [S2]; the huts were wattle and daub [S2]; a single (univallate) rampart enclosed the hilltop [S2]; the rampart had dry stone walls [S2]; the hilltop is triangular [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Timber huts stood in this hillfort [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN3963.html]; The huts stood on cleared bedrock [SUPPORTED: https://ubss.org.uk/resources/proceedings/vol8/UBSS_Proc_8_1_18-29.pdf]; This is an Iron Age hillfort [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN3963.html]; The huts were substantial [SUPPORTED: https://ubss.org.uk/resources/proceedings/vol8/UBSS_Proc_8_1_18-29.pdf]; The huts were wattle and daub [SUPPORTED: https://ubss.org.uk/resources/proceedings/vol8/UBSS_Proc_8_1_18-29.pdf]; A single rampart enclosed the hilltop [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN3963.html]; The rampart had dry stone walls [SUPPORTED: https://ubss.org.uk/resources/proceedings/vol8/UBSS_Proc_8_1_18-29.pdf]; The hilltop the rampart enclosed is triangular [SUPPORTED: https://hillforts.arch.ox.ac.uk/records/EN3963.html]"}]'::jsonb),
    ('6a55e68c-c08a-4c76-8685-fc501bbc0857'::uuid, 'card_description', 'The oldest standing building in the country is a Sabaean tower of dressed stone. It dates to about 700 BC and later became a Christian church, possibly as early as the 6th century AD.', '700 BC tower in the Sabaean style. Rededicated as a Christian church possibly by the 6th century AD — its reuse preserved it for 2,700 years. Considered the oldest standing structure of its kind.', 'teaser-card-s047-rollback:6a55e68c-c08a-4c76-8685-fc501bbc0857:card_description', 'rollback of teaser-card-s047: card_description ''700 BC tower in the Sabaean style. Rededicated as a Christian church possibly by the 6th century AD — its reuse preserved it for 2,700 years. Considered the oldest standing structure of its kind.'' restored on Great Yeha Temple of the Moon', 'b24e36688daf565c03685dae28cb0f32439a18d86f5abcd215dacfe83fe85403|c274dc83a30d9eccf54a7f1e9875d2ff65f204d9973d40383b742b395f88f302|c274dc83a30d9eccf54a7f1e9875d2ff65f204d9973d40383b742b395f88f302', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The oldest standing building in the country is a Sabaean tower of dressed stone. It dates to about 700 BC and later became a Christian church, possibly as early as the 6th century AD."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "it is the oldest standing building in the country [S2]; it is a Sabaean tower [S1]; it is built of dressed stone [S2]; it dates to about 700 BC [S1, S3]; it later became a Christian church [S4]; the conversion was possibly as early as the 6th century AD [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This is the oldest standing building in the country (Ethiopia). [SUPPORTED: https://www.historyhit.com/locations/the-yeha-temple/]; The building is Sabaean. [SUPPORTED: https://en.wikipedia.org/wiki/Sabaeans_in_the_Horn_of_Africa]; The building is a tower. [SUPPORTED: https://en.wikipedia.org/wiki/Architecture_of_Ethiopia]; The building is of dressed stone. [SUPPORTED: https://en.wikipedia.org/wiki/Sabaeans_in_the_Horn_of_Africa]; It dates to about 700 BC. [SUPPORTED: https://www.historyhit.com/locations/the-yeha-temple/]; It later became a Christian church. [SUPPORTED: https://www.historyhit.com/locations/the-yeha-temple/]; The conversion to a church possibly happened as early as the 6th century AD. [SUPPORTED: https://www.historyhit.com/locations/the-yeha-temple/]"}]'::jsonb),
    ('6adb5ed9-34b6-4985-8d4f-ece2fcdd31e4'::uuid, 'card_description', 'Roman coins dating back to the early 60s have been found in this fort''s town. The first fort was timber, likely built to command a river crossing, and the south side is yet to be confirmed.', 'Atop Castle Hill, Lancaster Roman Fort began in timber, probably around 80 AD, likely to command a crossing of the River Lune. Its south side is presumed to lie under Lancaster Castle.', 'teaser-card-s047-rollback:6adb5ed9-34b6-4985-8d4f-ece2fcdd31e4:card_description', 'rollback of teaser-card-s047: card_description ''Atop Castle Hill, Lancaster Roman Fort began in timber, probably around 80 AD, likely to command a crossing of the River Lune. Its south side is presumed to lie under Lancaster Castle.'' restored on Lancaster Roman Fort', 'ad5aa11b6b609312c3d24e97bbdc116b036d153db3b2ea982440a302b41bb283|d4f28b5d195870fc6b834168c8bdfcecbcbe31c374e384899162bef757d89842|d4f28b5d195870fc6b834168c8bdfcecbcbe31c374e384899162bef757d89842', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Roman coins dating back to the early 60s have been found in this fort''s town. The first fort was timber, likely built to command a river crossing, and the south side is yet to be confirmed."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-005 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Roman coins have been found in the fort''s town [S2]; the coins date back to the early 60s [S2]; the site is a fort in a town [S1]; the first fort was built of timber [S2]; it was likely built to command a river crossing [S3]; the south side of the fort is yet to be confirmed [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Roman coins have been found in this fort''s town [SUPPORTED: https://www.hslc.org.uk/wp-content/uploads/2017/05/148-2-Shotter.pdf]; The coins date back to the early 60s [SUPPORTED: https://en.wikipedia.org/wiki/Lancaster,_Lancashire]; The site is a Roman fort [SUPPORTED: https://lahs.archaeologyuk.org/Tour/Castle.htm]; The first fort was timber [SUPPORTED: https://lahs.archaeologyuk.org/Tour/Castle.htm]; The first fort was likely built to command a river crossing [SUPPORTED: https://en.wikipedia.org/wiki/Lancaster_Castle]; The south side is yet to be confirmed [SUPPORTED: https://lahs.archaeologyuk.org/Contrebis/Vol%2031%20Shotter%20Castle%20Hill.pdf]"}]'::jsonb),
    ('6c689af9-749f-4272-aa69-d1634dd8e4d5'::uuid, 'card_description', 'Two Anglo-Saxon burials were cut into the top of an older burial mound. Digs in 1894 found two chambers on its southeast side, and at least one held bone fragments, pottery and charcoal.', 'On a ridge overlooking valleys, Lyneham Long Barrow stretches 52 metres near a 1.8-metre-tall standing stone; later, two Anglo-Saxon burials were cut into the top of its mound.', 'teaser-card-s047-rollback:6c689af9-749f-4272-aa69-d1634dd8e4d5:card_description', 'rollback of teaser-card-s047: card_description ''On a ridge overlooking valleys, Lyneham Long Barrow stretches 52 metres near a 1.8-metre-tall standing stone; later, two Anglo-Saxon burials were cut into the top of its mound.'' restored on Lyneham Long Barrow', 'a164055bc032601e6ce2070d8c1b03bbdeb8e4b50044b957c734e35c8ace847a|6fef082e58b29985b6467ac0e92087c0bf96a6c7415ce0bbd9e3c193fe9f75bd|6fef082e58b29985b6467ac0e92087c0bf96a6c7415ce0bbd9e3c193fe9f75bd', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Two Anglo-Saxon burials were cut into the top of an older burial mound. Digs in 1894 found two chambers on its southeast side, and at least one held bone fragments, pottery and charcoal."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "two Anglo-Saxon burials were cut into the top of the mound [S8]; the mound already existed before those burials (older) [S8]; the mound is a burial mound (long barrow) [S1]; it was excavated in 1894 [S6]; the excavations found two chambers on its southeast side [S7]; at least one chamber held bone fragments, pottery and charcoal [S7]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Two Anglo-Saxon burials were cut into this burial mound. [SUPPORTED: https://historicoxfordshire.ashmolean.org/SitePages/lyneham.html]; The Anglo-Saxon burials were cut into the top of the mound. [SUPPORTED: https://www.british-history.ac.uk/vch/oxon/vol1/pp346-372]; The mound is an older (prehistoric) burial mound than the Anglo-Saxon burials. [SUPPORTED: https://www.british-history.ac.uk/vch/oxon/vol1/pp346-372]; Digs took place in 1894. [SUPPORTED: https://historicoxfordshire.ashmolean.org/SitePages/lyneham.html]; The 1894 digs found two chambers. [SUPPORTED: https://historicoxfordshire.ashmolean.org/SitePages/lyneham.html]; The two chambers are on the mound''s southeast side. [SUPPORTED: https://historicoxfordshire.ashmolean.org/SitePages/lyneham.html]; At least one chamber held bone fragments, pottery and charcoal. [SUPPORTED: https://historicoxfordshire.ashmolean.org/SitePages/lyneham.html]"}]'::jsonb),
    ('6cb3213a-bb68-4b7b-b45f-fab324033b3c'::uuid, 'card_description', 'Legend calls this stone cairn the grave of a 6th-century poet. Yet the Bronze Age cairn has no proven tie to him, and the capstone of its stone box grave, about 2m long, has fallen.', 'Legend calls Bedd Taliesin the grave of the poet Taliesin, though no connection is proven: a Bronze Age cairn in Ceredigion with a cist about 2m long, its capstone fallen.', 'teaser-card-s047-rollback:6cb3213a-bb68-4b7b-b45f-fab324033b3c:card_description', 'rollback of teaser-card-s047: card_description ''Legend calls Bedd Taliesin the grave of the poet Taliesin, though no connection is proven: a Bronze Age cairn in Ceredigion with a cist about 2m long, its capstone fallen.'' restored on Bedd Taliesin', '9a424c13a3122d08974d318aceb98e4116484cf29f14602e9124a98d5deeabf7|526cf6e1ea7b1f4deacc0d273e74052b35fb927b197543d63859479b87020f4a|526cf6e1ea7b1f4deacc0d273e74052b35fb927b197543d63859479b87020f4a', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Legend calls this stone cairn the grave of a 6th-century poet. Yet the Bronze Age cairn has no proven tie to him, and the capstone of its stone box grave, about 2m long, has fallen."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-010 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "legend calls the cairn the grave of a poet [S1]; the poet lived in the 6th century [S5]; the cairn is of stone [S2, S3]; the cairn dates to the Bronze Age [S2]; the cairn has no proven connection with the poet [S5]; it has a cist (stone box grave) about 2 m long [S3]; the capstone has fallen [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Legend calls this stone cairn the grave of a poet (Taliesin). [SUPPORTED: https://en.wikipedia.org/wiki/Taliesin]; The poet is a 6th-century poet. [SUPPORTED: https://en.wikipedia.org/wiki/Taliesin]; The site is a stone cairn. [SUPPORTED: https://coflein.gov.uk/en/site/303607/details/bedd-taliesin]; The cairn dates to the Bronze Age. [SUPPORTED: https://coflein.gov.uk/en/site/303607/details/bedd-taliesin]; The cairn has no proven tie to the poet. [SUPPORTED: https://coflein.gov.uk/en/site/303607/details/bedd-taliesin]; The cairn has a stone box grave (cist). [SUPPORTED: https://coflein.gov.uk/en/site/303607/details/bedd-taliesin]; The stone box grave (or its capstone) is about 2m long. [SUPPORTED: https://coflein.gov.uk/en/site/303607/details/bedd-taliesin]; The capstone of the stone box grave has fallen. [SUPPORTED: https://coflein.gov.uk/en/site/303607/details/bedd-taliesin]"}]'::jsonb),
    ('6e49927e-99cd-480d-8474-4da41b51ae46'::uuid, 'card_description', 'Four curved arms in a double outline are carved on a crag at a moor''s edge. Each arm, and an attached S-shape, encloses a so-called cup mark, on the only stone of its kind known in Britain.', 'On Woodhouse Crag, Ilkley Moor, the Swastika Stone bears a double-outlined swastika with a cup mark in each curved arm: the only one of its kind known in Britain, not verifiably dated.', 'teaser-card-s047-rollback:6e49927e-99cd-480d-8474-4da41b51ae46:card_description', 'rollback of teaser-card-s047: card_description ''On Woodhouse Crag, Ilkley Moor, the Swastika Stone bears a double-outlined swastika with a cup mark in each curved arm: the only one of its kind known in Britain, not verifiably dated.'' restored on Swastika Stone', 'c635b03f0092098b19c5b237c3c1f37a7f063392b370a021045c5bb3c95a8525|18099339e4e601c42ff6490f4659dbc59b164ea3fb4f14c14b17ed08a944483a|18099339e4e601c42ff6490f4659dbc59b164ea3fb4f14c14b17ed08a944483a', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Four curved arms in a double outline are carved on a crag at a moor''s edge. Each arm, and an attached S-shape, encloses a so-called cup mark, on the only stone of its kind known in Britain."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the design has four curved arms [S3]; the design has a double outline [S3]; the design is carved [S6]; it lies on a crag [S1]; the crag is at the edge of a moor [S1]; there is an attached S-shape [S3]; each arm and the S-shape encloses a so-called cup mark [S3]; it is the only stone of its kind known in Britain [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Four curved arms are carved on the stone. [SUPPORTED: http://www.stone-circles.org.uk/stone/swastikastone.htm]; The four curved arms are in a double outline. [SUPPORTED: https://commons.wikimedia.org/wiki/File:Ilkley_Moor_Swastika_Stone.jpg]; The carving is on a crag. [SUPPORTED: http://www.stone-circles.org.uk/stone/swastikastone.htm]; The crag is at a moor''s edge. [SUPPORTED: https://en.wikipedia.org/wiki/Ilkley_Moor]; Each arm encloses a so-called cup mark. [SUPPORTED: http://www.stone-circles.org.uk/stone/swastikastone.htm]; The S-shape is attached to the arms. [SUPPORTED: https://hikingtheworld.blog/engravings/ilkley-moor-swastika-stone/]; An attached S-shape also encloses a so-called cup mark. [SUPPORTED: http://www.stone-circles.org.uk/stone/swastikastone.htm]; It is the only stone of its kind known in Britain. [SUPPORTED: https://en.wikipedia.org/wiki/Verbeia]"}]'::jsonb),
    ('6faee7c5-517c-4de4-9809-b98a481fff2a'::uuid, 'card_description', 'Local legend says a prophet made his home and place of worship in a cave here. Pilgrims still visit the sacred cave, among the remains of houses built in typical Roman styles.', 'Late Roman settlement whose stone houses were likely summer residences for the Harran Plain. A cave here is venerated as the Prophet Shuayb''s dwelling — no comprehensive archaeological research done.', 'teaser-card-s047-rollback:6faee7c5-517c-4de4-9809-b98a481fff2a:card_description', 'rollback of teaser-card-s047: card_description "Late Roman settlement whose stone houses were likely summer residences for the Harran Plain. A cave here is venerated as the Prophet Shuayb''s dwelling — no comprehensive archaeological research done." restored on Şuayb Antik Şehri', 'd0b18e3acc590e48e766945f600d6182311bbedd7da349d691382a04366f062b|d97fcf660ef291624ac1c25a87f76a32135e6f08890333b0d82bae374b6cae74|d97fcf660ef291624ac1c25a87f76a32135e6f08890333b0d82bae374b6cae74', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Local legend says a prophet made his home and place of worship in a cave here. Pilgrims still visit the sacred cave, among the remains of houses built in typical Roman styles."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "according to local legend a prophet lived in a cave at the site [S2]; according to local legend the prophet used the cave as a place of worship [S2]; pilgrims still visit the cave [S3]; the cave is sacred [S3]; the site has remains of houses [S1]; the houses were built in typical Roman styles [S1]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Local legend says a prophet made his home in a cave here. [SUPPORTED: https://www.sanliurfa.bel.tr/icerik/236/625/suayb-antik-sehri]; Local legend says the prophet also made the cave his place of worship. [SUPPORTED: https://www.sanliurfa.bel.tr/icerik/236/625/suayb-antik-sehri]; Pilgrims still visit the cave. [SUPPORTED: https://www.sanliurfa.bel.tr/icerik/236/625/suayb-antik-sehri]; The cave is sacred (a shrine of the prophet). [SUPPORTED: https://www.kulturportali.gov.tr/turkiye/sanliurfa/gezilecekyer/suayb-antik-kenti--suayip-sehri-]; The cave lies among the remains of houses. [SUPPORTED: https://www.kulturportali.gov.tr/turkiye/sanliurfa/gezilecekyer/suayb-antik-kenti--suayip-sehri-]; The houses were built in typical Roman styles. [SUPPORTED: https://www.sanliurfa.bel.tr/icerik/236/625/suayb-antik-sehri]"}]'::jsonb),
    ('7008f483-697f-4f0b-b2c4-5b234d28d4c7'::uuid, 'card_description', 'Black on red pottery like that of the Indus Valley civilization was noted here. The Copper Age mound has two parts, a cone-shaped hill and a lower section that looks like a town.', NULL, 'teaser-card-s047-rollback:7008f483-697f-4f0b-b2c4-5b234d28d4c7:card_description', 'rollback of teaser-card-s047: card_description None restored on Lakhmir Mound', '0c95d0634d379db594d95aa7d15eb10b069f73e4499b1a80bb9367fe0b3d1426|774918b8ed99509c71f505153cf1f05268165530839519ca620f3b13a74281dc|774918b8ed99509c71f505153cf1f05268165530839519ca620f3b13a74281dc', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Black on red pottery like that of the Indus Valley civilization was noted here. The Copper Age mound has two parts, a cone-shaped hill and a lower section that looks like a town."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "black-on-red pottery was noted at the site [S3]; the pottery is like that of the Indus Valley civilization [S3]; it is a Copper Age (Chalcolithic) mound [S1]; the mound has two parts [S2]; one part is a cone-shaped hill [S2]; the other is a lower section that looks like a town [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The mound has two parts. [SUPPORTED: https://antiquities.sindhculture.gov.pk/index.php/mound/lakhmir-ji-mari-deh-nang-sehwan]; One part is a cone-shaped hill. [SUPPORTED: https://antiquities.sindhculture.gov.pk/index.php/mound/lakhmir-ji-mari-deh-nang-sehwan]; The other part is a lower section that looks like a town. [SUPPORTED: https://antiquities.sindhculture.gov.pk/index.php/mound/lakhmir-ji-mari-deh-nang-sehwan]; It is a Copper Age (Chalcolithic) mound. [SUPPORTED: https://en.wikipedia.org/wiki/Naig_Valley]; Pottery like that of the Indus Valley civilization was noted here. [SUPPORTED: https://ojs.plhr.org.pk/journal/article/download/206/158/313]; The Indus-like pottery noted here is black on red. [SUPPORTED, no proving quote: https://www.dawn.com/news/727095]"}]'::jsonb),
    ('70c04f92-593e-467b-8568-b585e1cdb58f'::uuid, 'card_description', 'Bones, charcoal and a coarse pot lay in a stone box at the circle''s heart. Two stones from that grave, now in a museum, bear cup and ring marks, and the circle probably ringed a cairn.', 'Near Long Meg and Her Daughters lies Little Meg, a small circle of large kerb stones, one still bearing concentric circles and a spiral; at its centre a cist held bones and charcoal.', 'teaser-card-s047-rollback:70c04f92-593e-467b-8568-b585e1cdb58f:card_description', 'rollback of teaser-card-s047: card_description ''Near Long Meg and Her Daughters lies Little Meg, a small circle of large kerb stones, one still bearing concentric circles and a spiral; at its centre a cist held bones and charcoal.'' restored on Little Meg', 'a14d777037b0a6062bf3138382382b9e2d4ebf43d93336388d7b915b9f502187|2b5ffefb4ff8b94a2a0f82250e9c50c15ab7ef033589e5856626bc01d5f25914|2b5ffefb4ff8b94a2a0f82250e9c50c15ab7ef033589e5856626bc01d5f25914', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Bones, charcoal and a coarse pot lay in a stone box at the circle''s heart. Two stones from that grave, now in a museum, bear cup and ring marks, and the circle probably ringed a cairn."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "bones were found in a stone box (cist) at the centre of the circle [S6]; charcoal was found there [S6]; a coarse pot was found there [S6]; the cist was a grave, the bones having been buried in it [S6]; two stones came from that cist [S7]; those two stones are now in a museum [S7]; they bear cup and ring marks [S7]; the circle probably surrounded a cairn [S1]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Bones, charcoal and a coarse pot lay in a stone box at the circle''s heart. [SUPPORTED: http://www.photographers-resource.co.uk/a_heritage/ancient/stone_circles/LG/little_meg_stone_circle.htm]; Bones lay in that stone box. [SUPPORTED: http://www.photographers-resource.co.uk/a_heritage/ancient/stone_circles/LG/little_meg_stone_circle.htm]; Charcoal lay in that stone box. [SUPPORTED: http://www.photographers-resource.co.uk/a_heritage/ancient/stone_circles/LG/little_meg_stone_circle.htm]; A coarse pot lay in that stone box. [SUPPORTED: http://www.photographers-resource.co.uk/a_heritage/ancient/stone_circles/LG/little_meg_stone_circle.htm]; Two stones came from that grave. [SUPPORTED: https://www.lakesguides.co.uk/html/lgaz/LK06968.htm]; Those stones from the grave bear cup and ring marks. [SUPPORTED: https://www.eden.gov.uk/leisure-culture-and-events/penrith-and-eden-museum/whats-on-at-the-museum/museums-permanent-displays/]; Those stones are now in a museum. [SUPPORTED: https://www.eden.gov.uk/leisure-culture-and-events/penrith-and-eden-museum/whats-on-at-the-museum/museums-permanent-displays/]; The circle probably ringed a cairn. [SUPPORTED: http://www.stone-circles.org.uk/stone/littlemeg.htm]"}]'::jsonb),
    ('722bf4c1-6dca-454a-9d27-89503114e75c'::uuid, 'card_description', 'Oil lamps turned up here in such numbers that one name means lamp cave. It once held a shrine to Pan and the nymphs, and three votive reliefs found inside are now in a national museum.', 'On Mount Parnes, the small Phyle Cave once held a sanctuary to Pan and the nymphs. So many oil lamps were found inside that it is also called Lychnospilia, the lamp cave.', 'teaser-card-s047-rollback:722bf4c1-6dca-454a-9d27-89503114e75c:card_description', 'rollback of teaser-card-s047: card_description ''On Mount Parnes, the small Phyle Cave once held a sanctuary to Pan and the nymphs. So many oil lamps were found inside that it is also called Lychnospilia, the lamp cave.'' restored on Phyle Cave', '2b17e1040d1383f02447e7df35b6dc07bf7b25bbe56b21713e62ee75f0fd9484|06b1bd2a60f2f1ee47109dcbdaec3d41a6380cdc791bca9015259e8fb34f8587|06b1bd2a60f2f1ee47109dcbdaec3d41a6380cdc791bca9015259e8fb34f8587', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Oil lamps turned up here in such numbers that one name means lamp cave. It once held a shrine to Pan and the nymphs, and three votive reliefs found inside are now in a national museum."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-005 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a large number of oil lamps was found at the site [S3]; one of the site''s names means lamp cave, because of those lamps [S3]; the site is a cave [S1, S3]; it once held a sanctuary to Pan and the nymphs [S2]; three votive reliefs were found inside [S6]; the three reliefs are now in a national museum [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "One name of the cave means lamp cave [SUPPORTED: http://www.aegeussociety.org/images/uploads/pdf/Mavridis-et-al-2013-introduction.pdf]; Oil lamps turned up here in large numbers [SUPPORTED: https://www.archaiologia.gr/blog/issue/%CF%83%CF%80%CE%AE%CE%BB%CE%B1%CE%B9%CE%B1-%CF%84%CE%B7%CF%82-%CE%B1%CF%84%CF%84%CE%B9%CE%BA%CE%AE%CF%82-%CE%B1%CF%86%CE%B9%CE%B5%CF%81%CF%89%CE%BC%CE%AD%CE%BD%CE%B1-%CF%83%CF%84%CE%B7-%CE%BB%CE%B1/]; The name comes from the number of lamps found [SUPPORTED: https://www.archaiologia.gr/blog/issue/%CF%83%CF%80%CE%AE%CE%BB%CE%B1%CE%B9%CE%B1-%CF%84%CE%B7%CF%82-%CE%B1%CF%84%CF%84%CE%B9%CE%BA%CE%AE%CF%82-%CE%B1%CF%86%CE%B9%CE%B5%CF%81%CF%89%CE%BC%CE%AD%CE%BD%CE%B1-%CF%83%CF%84%CE%B7-%CE%BB%CE%B1/]; It once held a shrine to Pan and the nymphs [SUPPORTED: https://www.perseus.tufts.edu/hopper/artifact?name=Athens,+NM+1448&object=Sculpture]; Votive reliefs were found inside [SUPPORTED: https://www.perseus.tufts.edu/hopper/artifact?name=Athens,+NM+1879&object=Sculpture]; Three votive reliefs found inside are now in a national museum [SUPPORTED: https://www.perseus.tufts.edu/hopper/artifact?name=Athens,+NM+1859&object=Sculpture]"}]'::jsonb),
    ('748bda90-84cd-452b-8cff-25d9185bab43'::uuid, 'card_description', 'Mnesikles may have built this two-aisled hall. Scholars believe the hall, raised circa 425 BC–410 BC for a cult founded after the Persian War, also served civic roles.', 'In the Ancient Agora of Athens stood the Stoa of Zeus, dedicated to Zeus Eleutherios, a cult founded after the Persian War. Researchers think Mnesikles may have built it.', 'teaser-card-s047-rollback:748bda90-84cd-452b-8cff-25d9185bab43:card_description', 'rollback of teaser-card-s047: card_description ''In the Ancient Agora of Athens stood the Stoa of Zeus, dedicated to Zeus Eleutherios, a cult founded after the Persian War. Researchers think Mnesikles may have built it.'' restored on Stoa of Zeus', 'e3936bc3217f49229b99cb85980778e5be8b7a4177138eb10eb89d3bfa841a21|8917f86577d688e5541e638137ab19dc0034ae563516fd618d7c42361d71154e|8917f86577d688e5541e638137ab19dc0034ae563516fd618d7c42361d71154e', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Mnesikles may have built this two-aisled hall. Scholars believe the hall, raised circa 425 BC–410 BC for a cult founded after the Persian War, also served civic roles."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Mnesikles may have built it [S4]; it is a two-aisled hall (stoa) [S1]; scholars believe it also served civic purposes [S3]; it was built circa 425-410 BC [S2]; it was built for a cult founded after the Persian War [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The hall was raised circa 425 BC–410 BC for a cult founded after the Persian War. [SUPPORTED: http://www.perseus.tufts.edu/hopper/artifact?name=Athens%2C+Stoa+of+Zeus+%28Eleutherios%29&object=Building]; Mnesikles may have built this hall. [SUPPORTED: http://www.perseus.tufts.edu/hopper/artifact?name=Athens%2C+Stoa+of+Zeus+%28Eleutherios%29&object=Building]; It is a two-aisled hall. [SUPPORTED: http://www.perseus.tufts.edu/hopper/artifact?name=Athens%2C+Stoa+of+Zeus+%28Eleutherios%29&object=Building]; The hall was raised circa 425 BC–410 BC. [SUPPORTED: https://www.greeceathensaegeaninfo.com/h-athens/ancient/agora-stoa-zeus.htm]; It was raised for a cult. [SUPPORTED: https://topostext.org/place/380237BSZe]; The cult was founded after the Persian War. [SUPPORTED: https://www.greeceathensaegeaninfo.com/h-athens/ancient/agora-stoa-zeus.htm]; Scholars believe the hall also served civic roles. [SUPPORTED: http://www.perseus.tufts.edu/hopper/artifact?name=Athens%2C+Stoa+of+Zeus+%28Eleutherios%29&object=Building]"}]'::jsonb),
    ('763e4a8b-eed2-495d-81db-35f83a3d5d82'::uuid, 'card_description', 'King Alfred the Great summoned his troops with this stone, legend tells. A person with the right skill can still make a booming sound by breathing into one of the holes the right way.', 'Blow into one of its holes the right way and the Blowing Stone, a perforated sarsen in Oxfordshire, booms. Legend says King Alfred summoned his troops with it for the Battle of Ashdown.', 'teaser-card-s047-rollback:763e4a8b-eed2-495d-81db-35f83a3d5d82:card_description', 'rollback of teaser-card-s047: card_description ''Blow into one of its holes the right way and the Blowing Stone, a perforated sarsen in Oxfordshire, booms. Legend says King Alfred summoned his troops with it for the Battle of Ashdown.'' restored on Blowing Stone', 'd2ec0fe1b487126893c2ee502e1127d9a0c0ecf1a3c8388edf3af4e4e22053c7|fea9828d644c7592d5ec5e7a67bc617ca51302ed49df4285bca38ec458480f57|fea9828d644c7592d5ec5e7a67bc617ca51302ed49df4285bca38ec458480f57', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "King Alfred the Great summoned his troops with this stone, legend tells. A person with the right skill can still make a booming sound by breathing into one of the holes the right way."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "according to legend King Alfred the Great summoned his troops with this stone [S5]; the stone can produce a booming sound [S4]; this requires a person with the required skill [S4]; the sound is made by blowing into one of the holes the right way [S4]; the stone has holes [S1, S4]; it can still do so today [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "King Alfred the Great summoned his troops with this stone, legend tells. [SUPPORTED: https://www.fdahs.org.uk/villages/kingston-lisle/]; The summoning of the troops by King Alfred is a legend. [SUPPORTED: https://lambourn.org/the-blowing-stone/]; A person can still make a sound with the stone today. [SUPPORTED: https://lambourn.org/the-blowing-stone/]; The sound is booming. [SUPPORTED: https://lambourn.org/the-blowing-stone/]; Making the sound needs the right skill. [SUPPORTED: https://lambourn.org/the-blowing-stone/]; The sound is made by breathing into one of the holes the right way. [SUPPORTED: https://lambourn.org/the-blowing-stone/]"}]'::jsonb),
    ('788f9236-c12f-4f94-9dc6-4f3a3d682626'::uuid, 'card_description', 'Three Latin inscriptions and one in Greek were engraved on one rock. That rock stands at the entrance to an enclosure of three large rocks, with hollows and access stairs.', 'Santuário Rupestre de Panóias is an enclosure of three large rocks with cavities opened in them and stairs built. On the entrance rock, Latin and Greek inscriptions describe the ritual.', 'teaser-card-s047-rollback:788f9236-c12f-4f94-9dc6-4f3a3d682626:card_description', 'rollback of teaser-card-s047: card_description ''Santuário Rupestre de Panóias is an enclosure of three large rocks with cavities opened in them and stairs built. On the entrance rock, Latin and Greek inscriptions describe the ritual.'' restored on Santuário Rupestre de Panóias', '117f503b1b5a5c89abf435f4fdc45d99f0eb16a1fce7b9031107867481174c40|d88e3c16abca5e706340bc3f34d85aad71ff13cbaa38f1af721bbfa86ab93b94|d88e3c16abca5e706340bc3f34d85aad71ff13cbaa38f1af721bbfa86ab93b94', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Three Latin inscriptions and one in Greek were engraved on one rock. That rock stands at the entrance to an enclosure of three large rocks, with hollows and access stairs."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "three Latin inscriptions were engraved on one rock [S4]; one Greek inscription was engraved on that rock [S4]; that rock is at the entrance of an enclosure [S4]; the enclosure has three large rocks [S3]; cavities were cut into the rocks [S3]; access stairs were built [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Three Latin inscriptions and one in Greek were engraved on one rock. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]; Three of the inscriptions are in Latin. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]; One inscription is in Greek. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]; The inscriptions were engraved on one rock. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]; That rock stands at the entrance to an enclosure. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]; The enclosure is of three large rocks. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]; The rocks have hollows. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]; The rocks have access stairs. [SUPPORTED: https://www.calendarios.info/santuario-de-panoias-vila-real/]"}]'::jsonb),
    ('78c3716d-79fb-46aa-82df-3a26d8ffd414'::uuid, 'card_description', 'A diadem was among the many silver goods in a grave shared by a woman and a man. The bulk of the goods went with the woman, and the couple lay beneath the floor of a large building.', 'At La Almoloya, a woman and a man lie beneath the floor of a large building, their grave holding numerous silver goods including a diadem. Radiocarbon dating suggests approximately 1700 BC.', 'teaser-card-s047-rollback:78c3716d-79fb-46aa-82df-3a26d8ffd414:card_description', 'rollback of teaser-card-s047: card_description ''At La Almoloya, a woman and a man lie beneath the floor of a large building, their grave holding numerous silver goods including a diadem. Radiocarbon dating suggests approximately 1700 BC.'' restored on La Almoloya', '46ff3867075332267bc1a6122ea5fb013e0fe872a9fef93b039d0db7eec03aaf|26ed993765dcd5386fe4411c95555c9e9463c2ff856b869f6299518eb4932e82|26ed993765dcd5386fe4411c95555c9e9463c2ff856b869f6299518eb4932e82', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-011", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A diadem was among the many silver goods in a grave shared by a woman and a man. The bulk of the goods went with the woman, and the couple lay beneath the floor of a large building."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-011 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a diadem was found in the grave [S5]; the grave held many silver goods [S5]; the grave held a woman and a man [S4]; most of the goods were associated with the woman [S5]; the couple was buried beneath the floor of a large building [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A diadem was among the silver goods in a grave at this site shared by a woman and a man (Grave 38). [SUPPORTED: https://www.uab.cat/web/newsroom/news-detail/elite-women-might-have-ruled-el-argar-4-000-years-ago-1345668003610.html?noticiaid=1345838033677]; The grave was shared by a woman and a man. [SUPPORTED: https://www.uab.cat/web/newsroom/news-detail/elite-women-might-have-ruled-el-argar-4-000-years-ago-1345668003610.html?noticiaid=1345838033677]; The grave held many silver goods. [SUPPORTED: https://www.uab.cat/web/newsroom/news-detail/elite-women-might-have-ruled-el-argar-4-000-years-ago-1345668003610.html?noticiaid=1345838033677]; The bulk of the goods went with the woman. [SUPPORTED: https://www.uab.cat/web/newsroom/news-detail/elite-women-might-have-ruled-el-argar-4-000-years-ago-1345668003610.html?noticiaid=1345838033677]; The couple lay beneath the floor of a large building. [SUPPORTED: https://www.uab.cat/web/newsroom/news-detail/elite-women-might-have-ruled-el-argar-4-000-years-ago-1345668003610.html?noticiaid=1345838033677]"}]'::jsonb),
    ('7ab48a71-0bbd-49a3-b562-563dc5e26bf6'::uuid, 'card_description', 'Shoes lay in a rubbish heap at this Roman fort. Other finds include coins, beads and a bronze piece shaped like a dolphin, at the highest stone-built Roman fort in Britain.', 'Whitley Castle, the highest stone-built Roman fort in Britain, is lozenge-shaped to fit the site. Its finds include altars to Hercules and Apollo and a bronze handle shaped like a dolphin.', 'teaser-card-s047-rollback:7ab48a71-0bbd-49a3-b562-563dc5e26bf6:card_description', 'rollback of teaser-card-s047: card_description ''Whitley Castle, the highest stone-built Roman fort in Britain, is lozenge-shaped to fit the site. Its finds include altars to Hercules and Apollo and a bronze handle shaped like a dolphin.'' restored on Whitley Castle', 'ff9654e579408a53423f8a12de1032fb74c2980e787efb1b979da3535791aefc|309fc9d065b7c886eb84a9404c25aab24240b4201b3af1b2fd0adc6bfb3f15a9|309fc9d065b7c886eb84a9404c25aab24240b4201b3af1b2fd0adc6bfb3f15a9', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Shoes lay in a rubbish heap at this Roman fort. Other finds include coins, beads and a bronze piece shaped like a dolphin, at the highest stone-built Roman fort in Britain."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-006 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "shoes were found in a midden (rubbish heap) at the site [S8]; the site is a Roman fort [S1]; other finds include coins [S8]; other finds include beads [S8]; other finds include a bronze piece shaped like a dolphin [S8]; it is the highest stone-built Roman fort in Britain [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This is the highest stone-built Roman fort in Britain. [SUPPORTED: https://northpennines.org.uk/location/epiacum-roman-fort/]; The site is a Roman fort. [SUPPORTED: https://epiacumheritage.org/history/the-romans/]; Shoes lay in a rubbish heap at this Roman fort. [SUPPORTED: https://epiacumheritage.org/history/the-romans/]; Other finds include coins. [SUPPORTED: https://epiacumheritage.org/history/the-romans/]; Other finds include beads. [SUPPORTED: https://epiacumheritage.org/about-us/research/]; Other finds include a bronze piece shaped like a dolphin. [SUPPORTED: https://www.thehistoryblog.com/archives/16323]"}]'::jsonb),
    ('7cff9dcb-732c-45c9-82be-8ee3096abcaa'::uuid, 'card_description', 'Only one piece of obsidian was found in this village on a high cliff. The stone was evidently still in use, but unlike in earlier times, obsidian had become extremely rare on the island.', 'Aghios Epiktitos Vrysi, at least 15 houses on a cliff 9 km east of Kyrenia, left awls and needles of a developed textile craft, and just one piece of obsidian, then extremely rare in Cyprus.', 'teaser-card-s047-rollback:7cff9dcb-732c-45c9-82be-8ee3096abcaa:card_description', 'rollback of teaser-card-s047: card_description ''Aghios Epiktitos Vrysi, at least 15 houses on a cliff 9 km east of Kyrenia, left awls and needles of a developed textile craft, and just one piece of obsidian, then extremely rare in Cyprus.'' restored on Aghios Epiktitos Vrysi', '1cc540456c175a7c0cca232dd4d7f67203693a86be862c1da9f8c4bad516cfc5|9726e913954fa7b7470f49d0b17e139e98952912ca1f33228cf2f102ad0ebd70|9726e913954fa7b7470f49d0b17e139e98952912ca1f33228cf2f102ad0ebd70', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite1-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Only one piece of obsidian was found in this village on a high cliff. The stone was evidently still in use, but unlike in earlier times, obsidian had become extremely rare on the island."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check1-003 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "only one piece of obsidian was found at the site [S5]; the site was a village [S3]; the village lies on a high cliff [S1]; obsidian was evidently still in use at that time [S4]; unlike in earlier times, obsidian had become extremely rare on the island (Cyprus) [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Only one piece of obsidian was found in this village (Ayios Epiktitos Vrysi). [SUPPORTED: https://link.springer.com/article/10.1007/s11457-020-09277-7]; The village lies on a high cliff. [SUPPORTED: http://kypros.org/Occupied_Cyprus/epiktitos/archaeological/Vrysi1.htm]; The stone (obsidian) was evidently still in use. [SUPPORTED: https://link.springer.com/article/10.1007/s11457-020-09277-7]; Obsidian had been less rare on the island in earlier times. [SUPPORTED: https://link.springer.com/article/10.1007/s11457-020-09277-7]; By then obsidian had become extremely rare on the island. [SUPPORTED: https://link.springer.com/article/10.1007/s11457-020-09277-7]"}]'::jsonb),
    ('82b9ba8e-bc9a-405a-afe2-fcb210a5d278'::uuid, 'card_description', 'Carved felines, people and the sun share these rocks with llamas and vicuñas. The site lies 3,449 metres up, and the name of the complex means with a little llama, or llamas.', 'High in the Apurímac Region, at 3,449 metres, the petroglyphs of Llamachayuq, Quechua for ''with a little llama'', show llamas, vicuñas, felines, people and the sun.', 'teaser-card-s047-rollback:82b9ba8e-bc9a-405a-afe2-fcb210a5d278:card_description', 'rollback of teaser-card-s047: card_description "High in the Apurímac Region, at 3,449 metres, the petroglyphs of Llamachayuq, Quechua for ''with a little llama'', show llamas, vicuñas, felines, people and the sun." restored on Llamachayuq', '1750b3bc66a064e1016caf7a501ffd16626fe52d2f2a219ce23f489d16d3c3c7|b5c741e0dd1d417077a606781c6cdd1cb03fd3ec3aa26630aa95cf6d7fad2a19|b5c741e0dd1d417077a606781c6cdd1cb03fd3ec3aa26630aa95cf6d7fad2a19', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-012", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Carved felines, people and the sun share these rocks with llamas and vicuñas. The site lies 3,449 metres up, and the name of the complex means with a little llama, or llamas."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the rocks carry carved images (petroglyphs) [S1]; the images show felines, people and the sun [S3]; the images also show llamas and vicunas [S3]; the site lies at 3,449 metres [S3]; it is an archaeological complex [S1]; the name of the complex means ''with a little llama (or llamas)'' [S1]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-021 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Carved felines share these rocks with llamas and vicuñas (petroglyphs of Llamachayoq). [SUPPORTED: https://www.turismoperuano.com/peroglifos-de-llamachayoq-apurimac]; Carved people share the rocks. [SUPPORTED: https://www.turismoperuano.com/peroglifos-de-llamachayoq-apurimac]; A carved sun shares the rocks. [SUPPORTED: https://www.turismoperuano.com/peroglifos-de-llamachayoq-apurimac]; The rocks carry carved llamas and vicuñas. [SUPPORTED: https://www.turismoperuano.com/peroglifos-de-llamachayoq-apurimac]; The site lies 3,449 metres up. [SUPPORTED: https://www.turismoperuano.com/peroglifos-de-llamachayoq-apurimac]; The site is a complex of rocks with carvings. [SUPPORTED: https://books.openedition.org/ifea/11679?lang=en]; The name of the complex means ''with a little llama, or llamas''. [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('852f3856-ecaa-4bab-82c8-a0ab2d11f94f'::uuid, 'card_description', 'A wall of serpents remains mostly intact on three sides of this pyramid. The site holds the earliest example yet found of the typical Aztec double pyramid, two temples on joined bases.', 'Tenayuca holds the earliest Aztec double pyramid yet found. A double stairway climbs to where the temples of Tlaloc and Huitzilopochtli once stood, above a wall of serpents.', 'teaser-card-s047-rollback:852f3856-ecaa-4bab-82c8-a0ab2d11f94f:card_description', 'rollback of teaser-card-s047: card_description ''Tenayuca holds the earliest Aztec double pyramid yet found. A double stairway climbs to where the temples of Tlaloc and Huitzilopochtli once stood, above a wall of serpents.'' restored on Tenayuca', 'bd84fca2dfd2dab2b5f6e5cfb224cc2f02063dea66d590283ea64da91fd34569|3072b61e605ce537a913568be2a216222bc68bed86ece68c3bd454e26e28b130|3072b61e605ce537a913568be2a216222bc68bed86ece68c3bd454e26e28b130', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-012", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A wall of serpents remains mostly intact on three sides of this pyramid. The site holds the earliest example yet found of the typical Aztec double pyramid, two temples on joined bases."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a wall of serpents remains mostly intact [S5]; the serpent wall runs on three sides of the pyramid''s base [S5]; the site has a pyramid [S5, S6]; the site holds the earliest example yet found of the typical Aztec double pyramid [S4]; a double pyramid consists of joined bases supporting two temples [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "This pyramid has a wall of serpents. [SUPPORTED: https://lugares.inah.gob.mx/en/node/4465]; The wall of serpents is on three sides of this pyramid. [SUPPORTED: https://www.inah.gob.mx/foto-del-dia/una-muralla-de-serpientes]; The wall of serpents remains mostly intact. [SUPPORTED: https://es.wikipedia.org/wiki/Tenayuca]; The site holds the earliest example yet found of the typical Aztec double pyramid. [SUPPORTED: https://mexicocity.cdmx.gob.mx/venues/tenayuca-ruins/?lang=en]; The typical Aztec double pyramid consists of two temples on joined bases. [SUPPORTED: https://arqueologiamexicana.mx/mexico-antiguo/tenayuca-estado-de-mexico]"}]'::jsonb),
    ('8ece5123-5b53-4545-929d-0519137c13ea'::uuid, 'card_description', 'An 8 m broad arch of wedge stones let people walk across a canal. The bridge has a single span of 2.8 m, the same as the width of the canal, and the arch has a surprisingly low rise.', 'Near the Akandia Bay, the Rhodes Footbridge crosses an artificial canal on a surprisingly low arch of wedge-shaped poros stones: the oldest known Greek bridge with a voussoir arch.', 'teaser-card-s047-rollback:8ece5123-5b53-4545-929d-0519137c13ea:card_description', 'rollback of teaser-card-s047: card_description ''Near the Akandia Bay, the Rhodes Footbridge crosses an artificial canal on a surprisingly low arch of wedge-shaped poros stones: the oldest known Greek bridge with a voussoir arch.'' restored on Rhodes Footbridge', 'eaf0a3d0e9ad81191fa2fe76541f38787f541e8394d497f77fbb392fe78fdd49|f0bb756ac785ed4ac768738896a48282c98ac391f7e692a7b0978e7dd3afa095|f0bb756ac785ed4ac768738896a48282c98ac391f7e692a7b0978e7dd3afa095', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-012", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "An 8 m broad arch of wedge stones let people walk across a canal. The bridge has a single span of 2.8 m, the same as the width of the canal, and the arch has a surprisingly low rise."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "an 8 m broad arch crosses a canal [S6]; the arch is made of wedge-shaped stones [S6]; the arch served as a footbridge for people to cross the canal [S6]; the bridge has a single span of 2.8 m [S7]; the span equals the width of the canal [S7]; the arch has a surprisingly low rise [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "An arch let people walk across a canal. [SUPPORTED: https://de.wikipedia.org/wiki/Steg_von_Rhodos]; The arch is made of wedge stones. [SUPPORTED: https://de.wikipedia.org/wiki/Steg_von_Rhodos]; The arch is 8 m broad. [SUPPORTED: https://de.wikipedia.org/wiki/Steg_von_Rhodos]; The bridge has a single span. [SUPPORTED: https://de.wikipedia.org/wiki/Steg_von_Rhodos]; The span is 2.8 m. [SUPPORTED: https://de.wikipedia.org/wiki/Steg_von_Rhodos]; The span is the same as the width of the canal. [SUPPORTED: https://de.wikipedia.org/wiki/Steg_von_Rhodos]; The arch has a surprisingly low rise. [SUPPORTED: https://de.wikipedia.org/wiki/Steg_von_Rhodos]"}]'::jsonb),
    ('90cfd278-3aac-40b9-9d3c-d50a40bd3051'::uuid, 'card_description', 'Around thirty small stones remain of a ring that may once have held around 100. Clear gaps break the north and west sides of the ring, about 36.4 metres across, on a heath slope.', 'On Exmoor heathland, the Withypool Stone Circle keeps around thirty small gritstones in a ring about 36.4 metres across, where there may once have been around 100. Gaps open north and west.', 'teaser-card-s047-rollback:90cfd278-3aac-40b9-9d3c-d50a40bd3051:card_description', 'rollback of teaser-card-s047: card_description ''On Exmoor heathland, the Withypool Stone Circle keeps around thirty small gritstones in a ring about 36.4 metres across, where there may once have been around 100. Gaps open north and west.'' restored on Withypool Stone Circle', '0ce57267a1dde7d21a6556929094e09f0dc3923b26dc8fd8f0c2fc754d2f3702|a2e0f944bec3fa675da3161d930da4c8b17bd0347a2ad8ae0c178bcb62a121fd|a2e0f944bec3fa675da3161d930da4c8b17bd0347a2ad8ae0c178bcb62a121fd', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Around thirty small stones remain of a ring that may once have held around 100. Clear gaps break the north and west sides of the ring, about 36.4 metres across, on a heath slope."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-006 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "around thirty small stones remain [S5]; the monument is a ring of stones [S1]; there may originally have been around 100 stones [S5]; there are conspicuous gaps on the northern and western sides [S5]; the ring is about 36.4 metres in diameter [S4]; it lies on a slope, on heathland [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Around thirty stones remain of a ring (a stone circle). [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO8682]; The remaining stones are small. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO8682]; The ring may once have held around 100 stones. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO8682]; Clear gaps break the north and west sides of the ring. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO8682]; The ring is about 36.4 metres across. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO8682]; The ring is on a heath slope. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO8682]"}]'::jsonb),
    ('940444fb-1897-4c1f-bdc2-30e967df95c8'::uuid, 'card_description', 'Girls of marriageable age ask this rock how long until they marry. Shaped like a mushroom, the granite stone bears a cross believed carved to make an ancient ritual Christian.', 'A granite stone shaped like a mushroom, more than two meters high: at the Rocha dos Namorados, girls of marriageable age still consult the rock to learn how long until they marry.', 'teaser-card-s047-rollback:940444fb-1897-4c1f-bdc2-30e967df95c8:card_description', 'rollback of teaser-card-s047: card_description ''A granite stone shaped like a mushroom, more than two meters high: at the Rocha dos Namorados, girls of marriageable age still consult the rock to learn how long until they marry.'' restored on Rocha dos Namorados', 'd140e37e636d089c895374e6fd750babf437cb152f801e3d361b15e79843fda4|dd7d621daf0e9f950a69bc8a5767e6e031a6ffe24b34ef4875903e9ea4219d57|dd7d621daf0e9f950a69bc8a5767e6e031a6ffe24b34ef4875903e9ea4219d57', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-012", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Girls of marriageable age ask this rock how long until they marry. Shaped like a mushroom, the granite stone bears a cross believed carved to make an ancient ritual Christian."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-012 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "girls of marriageable age consult the rock [S5]; they consult it to find out how long until they marry [S5]; the stone is granite [S1]; the stone is shaped like a mushroom [S4]; the stone bears a carved cross [S2]; the cross is believed to have been carved to Christianise an ancient ritual [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-022 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Girls of marriageable age ask this rock how long until they marry. [SUPPORTED: https://www.cm-reguengos-monsaraz.pt/locais/rocha-dos-namorados/]; The stone is shaped like a mushroom. [SUPPORTED: https://www.cm-reguengos-monsaraz.pt/locais/rocha-dos-namorados/]; The stone is granite. [SUPPORTED: https://www.cm-reguengos-monsaraz.pt/locais/rocha-dos-namorados/]; The stone bears a cross. [SUPPORTED: https://viagens.sapo.pt/viajar/viajar-portugal/artigos/quer-saber-se-vai-casar-o-menir-dos-namorados-responde]; The cross is believed carved to make a ritual Christian. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=13850]; The ritual is ancient. [SUPPORTED: https://www.cm-reguengos-monsaraz.pt/locais/rocha-dos-namorados/]"}]'::jsonb),
    ('96938167-cc5f-44fa-b3fd-2ab39fad89a7'::uuid, 'card_description', '20 stones remain in one prehistoric ring and 29 in its twin to the south. Their centre points line up almost exactly north to south, and a dig found charcoal fragments inside the circles.', 'North of Postbridge on Dartmoor stand the Grey Wethers: two stone circles, each approximately 33 m across and less than five metres apart, aligned almost exactly north to south.', 'teaser-card-s047-rollback:96938167-cc5f-44fa-b3fd-2ab39fad89a7:card_description', 'rollback of teaser-card-s047: card_description ''North of Postbridge on Dartmoor stand the Grey Wethers: two stone circles, each approximately 33 m across and less than five metres apart, aligned almost exactly north to south.'' restored on Grey Wethers', '92d12b38604adf56a918b230a3526c16b9e03a3d6b4215a1f12b6804bdfe745f|2fb5ba5137aaaef5e6ef406acd6e24eccea47d169800d7d93e559e429e4ec5f3|2fb5ba5137aaaef5e6ef406acd6e24eccea47d169800d7d93e559e429e4ec5f3', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "20 stones remain in one prehistoric ring and 29 in its twin to the south. Their centre points line up almost exactly north to south, and a dig found charcoal fragments inside the circles."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-006 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "one circle (the northern) has 20 stones remaining [S4]; the southern circle has 29 stones remaining [S4]; the site is a pair of prehistoric stone circles [S1]; the two circles are twins (a like pair) [S1, S2]; their centre points are aligned almost exactly north to south [S3]; an excavation found charcoal fragments within the circles [S5]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "There are two rings, one the twin of the other, the twin lying to the south (a pair of stone circles). [SUPPORTED: https://www.dartmoorwalks.org.uk/resource/circles.php]; The rings are prehistoric. [SUPPORTED: https://www.legendarydartmoor.co.uk/2016/03/17/grey_wethers2/]; 20 stones remain in one ring (the northern one). [SUPPORTED: https://www.legendarydartmoor.co.uk/2016/03/17/grey_wethers2/]; 29 stones remain in its twin to the south. [SUPPORTED: https://www.legendarydartmoor.co.uk/2016/03/17/grey_wethers2/]; Their centre points line up almost exactly north to south. [SUPPORTED: https://www.dartmoorwalks.org.uk/resource/circles.php]; A dig found charcoal fragments inside the circles. [SUPPORTED: https://www.legendarydartmoor.co.uk/2016/03/17/grey_wethers2/]"}]'::jsonb),
    ('99115b5a-460c-41e5-98f0-be47a7235402'::uuid, 'card_description', 'A carved altar 1.3 m tall stands inside a cave that resembles a human vulva. The cave''s inside resembles a uterus, and historians believe the Thracian sanctuary was once a fertility shrine.', 'In the Eastern Rhodope Mountains, the Utroba Cave resembles a human vulva, its inside a uterus. A carved altar stands within; historians believe it was once used as a fertility shrine.', 'teaser-card-s047-rollback:99115b5a-460c-41e5-98f0-be47a7235402:card_description', 'rollback of teaser-card-s047: card_description ''In the Eastern Rhodope Mountains, the Utroba Cave resembles a human vulva, its inside a uterus. A carved altar stands within; historians believe it was once used as a fertility shrine.'' restored on Utroba Cave', 'b5929c520841e00777491df9d4e654352785509719a428447c957a913de73b16|8833ffb12b29ff67efbff231d611e2fbf662715fcdb195e2f42055590f0485b8|8833ffb12b29ff67efbff231d611e2fbf662715fcdb195e2f42055590f0485b8', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-013", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A carved altar 1.3 m tall stands inside a cave that resembles a human vulva. The cave''s inside resembles a uterus, and historians believe the Thracian sanctuary was once a fertility shrine."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there is a carved altar inside the cave [S7]; the altar is 1.3 m tall [S7]; the cave resembles a human vulva [S2]; the inside of the cave resembles a uterus [S5]; it is a sanctuary [S1]; it is Thracian [S2]; historians believe it was once used as a fertility shrine [S3]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "The altar is carved (cut into the rock) [SUPPORTED: https://uchiteli.bg/interesting/peshtera-utrobata/373]; The altar stands inside the cave [SUPPORTED: https://uchiteli.bg/interesting/peshtera-utrobata/373]; The altar is 1.3 m tall [SUPPORTED: https://uchiteli.bg/interesting/peshtera-utrobata/373]; The cave resembles a human vulva [SUPPORTED: https://uchiteli.bg/interesting/peshtera-utrobata/373]; The cave''s inside resembles a uterus [SUPPORTED: https://visitkardzhali.com/en/listing/pesthera-utrobata/]; The cave is a Thracian sanctuary [SUPPORTED: https://uchiteli.bg/interesting/peshtera-utrobata/373]; Historians (scholars) hold a view on the sanctuary''s former use [SUPPORTED: https://ahrida.org/landmark/cave-utrobata/]; The sanctuary was once a fertility shrine [SUPPORTED: https://ahrida.org/landmark/cave-utrobata/]"}]'::jsonb),
    ('9a4ccc75-d0d1-4bf8-8068-ef4cf3221aaf'::uuid, 'card_description', 'A circular hole about 43 cm across sits near the base of a triangular standing stone. The stone stands 2.3 m high, and its name comes from a Cornish term for a stone with a hole.', 'Near Gweek stands the Tolvan Holed Stone, the largest holed stone in Cornwall: a triangular stone 2.3 m high, pierced near its base by a hole approximately 43 cm in diameter.', 'teaser-card-s047-rollback:9a4ccc75-d0d1-4bf8-8068-ef4cf3221aaf:card_description', 'rollback of teaser-card-s047: card_description ''Near Gweek stands the Tolvan Holed Stone, the largest holed stone in Cornwall: a triangular stone 2.3 m high, pierced near its base by a hole approximately 43 cm in diameter.'' restored on Tolvan Holed Stone', '37e29f01bad6fea3f7e5cc90405c90c28bf4abb4b22e2104781410f9ba8c4528|564cb5a490c5920643f1c8f4666e5d40cc115a7f7c8207876d7e98b5b8fa3b2b|564cb5a490c5920643f1c8f4666e5d40cc115a7f7c8207876d7e98b5b8fa3b2b', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-013", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A circular hole about 43 cm across sits near the base of a triangular standing stone. The stone stands 2.3 m high, and its name comes from a Cornish term for a stone with a hole."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there is a circular hole near the base of the stone [S3]; the hole is about 43 cm across [S3]; it is a triangular standing stone [S1]; the stone is 2.3 m high [S2]; its name comes from a Cornish term meaning holed stone [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-023 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A hole sits near the base of the standing stone [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=7474]; The hole is circular [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=7474]; The hole is about 43 cm across [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=7474]; The standing stone is triangular [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=7474]; It is a standing stone (upright) [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=7474]; The stone stands 2.3 m high [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=7474]; Its name comes from a Cornish term for a stone with a hole [SUPPORTED: https://heritageaction.wordpress.com/2021/12/23/the-tolvan-stone/]"}]'::jsonb),
    ('9bedafde-94b7-40d2-a064-4130c224d7ef'::uuid, 'card_description', 'Willibrord, a famous missionary, reshaped this stone by hand, says tradition. The standing stone is now a Christian monument about 3.5 metres high, with two figure niches cut in the rock.', 'By a wayside on the Ferschweiler Plateau stands the Fraubillen Cross, a roughly 5,000-year-old menhir that, according to tradition, the missionary Willibrord reshaped by hand into a cross.', 'teaser-card-s047-rollback:9bedafde-94b7-40d2-a064-4130c224d7ef:card_description', 'rollback of teaser-card-s047: card_description ''By a wayside on the Ferschweiler Plateau stands the Fraubillen Cross, a roughly 5,000-year-old menhir that, according to tradition, the missionary Willibrord reshaped by hand into a cross.'' restored on Fraubillen Cross', '9767eb5ea377c27d88107791596c3144939052f78041dd4d40275fa9277db846|5fbd9c2a6df7260679431266dc5672f5f4aa355f4ae726151c2942682b65de12|5fbd9c2a6df7260679431266dc5672f5f4aa355f4ae726151c2942682b65de12', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Willibrord, a famous missionary, reshaped this stone by hand, says tradition. The standing stone is now a Christian monument about 3.5 metres high, with two figure niches cut in the rock."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-006 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "according to tradition, Willibrord reshaped the stone [S3]; according to tradition, he did it by hand [S3]; Willibrord was a famous missionary [S3]; the object is a standing stone (menhir) [S1]; the reshaped stone is today a Christian monument [S1, S3, S5]; today it is about 3.5 metres high [S5]; two niches for figures have been cut into the rock [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-006 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Willibrord reshaped this stone, says tradition. [SUPPORTED: https://tw.strahlen.org/praehistorie/rheinlandpfalz/ferschweilerkreuz.html]; Tradition says he reshaped it by hand (himself). [SUPPORTED: https://kulturdb.de/einobjekt.php?id=7254]; Willibrord was a famous missionary. [SUPPORTED: https://www.newadvent.org/cathen/15645a.htm]; The object is a standing stone (a menhir). [SUPPORTED: https://tw.strahlen.org/praehistorie/rheinlandpfalz/ferschweilerkreuz.html]; The standing stone is now a Christian monument. [SUPPORTED: https://tw.strahlen.org/praehistorie/rheinlandpfalz/ferschweilerkreuz.html]; The monument is about 3.5 metres high. [SUPPORTED: https://fr.wikipedia.org/wiki/Fraubillenkreuz]; Two figure niches are cut in the rock. [SUPPORTED: https://tw.strahlen.org/praehistorie/rheinlandpfalz/ferschweilerkreuz.html]"}]'::jsonb),
    ('9d58f665-8cc3-4438-9dc5-99885deb90d0'::uuid, 'card_description', 'Rings of broken stalagmites lie 336 metres from the entrance of a cave. Researchers state that early Neanderthals, the only humans there at the time, must have built them.', 'Deep in Bruniquel Cave, 336 metres from the entrance, lie rings of broken stalagmites dated as 176.5 thousand years old, with traces of fire. Researchers say early Neanderthals built them.', 'teaser-card-s047-rollback:9d58f665-8cc3-4438-9dc5-99885deb90d0:card_description', 'rollback of teaser-card-s047: card_description ''Deep in Bruniquel Cave, 336 metres from the entrance, lie rings of broken stalagmites dated as 176.5 thousand years old, with traces of fire. Researchers say early Neanderthals built them.'' restored on Bruniquel Cave', 'd061ab3a1cbdd17c2d3505dea2fefcec3b4c34062cd31868102e56d600f88248|bf9dd4c6534f6041273e08607c246c8e88eef508bd0798ba58cf01aa3554c809|bf9dd4c6534f6041273e08607c246c8e88eef508bd0798ba58cf01aa3554c809', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-013", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Rings of broken stalagmites lie 336 metres from the entrance of a cave. Researchers state that early Neanderthals, the only humans there at the time, must have built them."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-013 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "there are ring structures made of broken stalagmites [S2]; they lie 336 metres from the cave entrance [S2]; researchers state that early Neanderthals must have built them [S4]; early Neanderthals were the only humans in the area at that time [S4]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-024 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Rings of broken stalagmites lie in a cave (Bruniquel Cave). [SUPPORTED: https://www.nature.com/articles/nature18291]; The rings lie 336 metres from the entrance of the cave. [SUPPORTED: https://www.nature.com/articles/nature18291]; Researchers state that early Neanderthals must have built them. [SUPPORTED: https://www.nature.com/articles/nature18291]; Early Neanderthals were the only humans there at the time. [SUPPORTED: https://psmag.com/news/the-deep-cave-structures-left-behind-by-neanderthals/]"}]'::jsonb),
    ('9f795d88-5e93-4fdb-9bde-0708ddb21b6d'::uuid, 'card_description', 'Less than 5 metres high, this ruined wall ran for over 600 metres. The buttressed wall is held to be Roman, and by that account its reservoir seems to have watered a town and farmland.', 'On the River Amarguillo lie the ruins of the Consuegra Dam, a Roman buttress dam of the 3rd or 4th century AD: less than 5 metres high, yet remarkably long, over 600 metres.', 'teaser-card-s047-rollback:9f795d88-5e93-4fdb-9bde-0708ddb21b6d:card_description', 'rollback of teaser-card-s047: card_description ''On the River Amarguillo lie the ruins of the Consuegra Dam, a Roman buttress dam of the 3rd or 4th century AD: less than 5 metres high, yet remarkably long, over 600 metres.'' restored on Consuegra Dam', 'a6b8cf051da10850e7d7e37ba946b36e36724539de96af7f94c9eab17c42b500|216c3bd7799efac800d6b38bdeb651be2a65fbd5868f0630b1e35d025c485c8c|216c3bd7799efac800d6b38bdeb651be2a65fbd5868f0630b1e35d025c485c8c', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-rewrite-v-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Less than 5 metres high, this ruined wall ran for over 600 metres. The buttressed wall is held to be Roman, and by that account its reservoir seems to have watered a town and farmland."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-v-007 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the structure is less than 5 metres high [S4]; it is ruined [S1]; it ran for over 600 metres [S4]; it is a buttressed structure [S1]; it is held to be Roman [S1]; it had a reservoir [S5]; the reservoir seems to have supplied water to a town [S5]; the reservoir seems to have irrigated farmland [S5]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify2-007 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "this ruined wall ... The buttressed wall ... its reservoir (the site is a long wall that is taken to have dammed a reservoir) [SUPPORTED: https://es.wikipedia.org/wiki/Presa_de_Consuegra]; this ruined wall ran for over 600 metres [SUPPORTED: https://cultura.castillalamancha.es/patrimonio/catalogo-patrimonio-cultural/presa-romana-de-consuegra]; Less than 5 metres high [SUPPORTED: https://www.chguadiana.es/node/6762]; this ruined wall (the wall is ruined) [SUPPORTED: https://www.chguadiana.es/node/6762]; The buttressed wall (the wall has buttresses) [SUPPORTED: https://cultura.castillalamancha.es/patrimonio/catalogo-patrimonio-cultural/presa-romana-de-consuegra]; The buttressed wall is held to be Roman [SUPPORTED: https://es.wikipedia.org/wiki/Presa_de_Consuegra]; by that account its reservoir (on the Roman-dam account the wall held a reservoir) [SUPPORTED: https://es.wikipedia.org/wiki/Presa_de_Consuegra]; by that account its reservoir seems to have watered a town [SUPPORTED: https://cultura.castillalamancha.es/patrimonio/catalogo-patrimonio-cultural/presa-romana-de-consuegra]; by that account its reservoir seems to have watered farmland [SUPPORTED: https://cultura.castillalamancha.es/patrimonio/catalogo-patrimonio-cultural/presa-romana-de-consuegra]"}]'::jsonb),
    ('a28e4962-5513-4955-b1e0-d6a8f8f244cc'::uuid, 'card_description', 'A farmer ploughing a field in 1931 hit an obstacle: a stone tomb. Inside, 20 vessels placed on the chamber floor and later covered in human ashes were almost fully preserved.', 'In 1931 a farmer ploughing near Marburg encountered an obstacle: the Lohra Megalithic Tomb, a large main chamber with a small open antechamber, its dead cremated.', 'teaser-card-s047-rollback:a28e4962-5513-4955-b1e0-d6a8f8f244cc:card_description', 'rollback of teaser-card-s047: card_description ''In 1931 a farmer ploughing near Marburg encountered an obstacle: the Lohra Megalithic Tomb, a large main chamber with a small open antechamber, its dead cremated.'' restored on Lohra Megalithic Tomb', '7e96c6f5ce2762d61d042297a853c6963c4608b5929d7f9f1fb44a03041e9878|57b6f7733a5f083a4ef404aa59e6aa9b67e64b592534c934bbc7437b642dc2a4|57b6f7733a5f083a4ef404aa59e6aa9b67e64b592534c934bbc7437b642dc2a4', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A farmer ploughing a field in 1931 hit an obstacle: a stone tomb. Inside, 20 vessels placed on the chamber floor and later covered in human ashes were almost fully preserved."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "a farmer was ploughing a field [S5]; this happened in 1931 [S5]; he hit an obstacle [S5]; the obstacle was the tomb, a megalithic (stone) tomb [S1, S5]; 20 vessels had been placed on the chamber floor [S8]; they were later covered in human ashes [S8]; they were almost fully preserved [S8]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "A farmer ploughing a field in 1931 came upon this stone tomb [SUPPORTED: https://www.ich-geh-wandern.de/lohra]; The farmer hit an obstacle while ploughing [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Lohra]; It is a stone tomb [SUPPORTED: https://www.ich-geh-wandern.de/lohra]; Inside were 20 vessels [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Lohra]; The vessels had been placed on the chamber floor [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Lohra]; The vessels were later covered in human ashes [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Lohra]; The vessels were almost fully preserved [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Lohra]"}]'::jsonb),
    ('a9a32ee2-bd62-4fe4-8515-0ccdda65a7ee'::uuid, 'card_description', 'About 11 metres under water lies a Middle Stone Age settlement. Rising waters swamped it and covered it in silt and mud, and experts have found burnt flints, mounds of timbers and pits.', 'In approximately 11 metres of water off the Isle of Wight lies Bouldnor Cliff, a settlement of about 8,000 years ago: burnt flints, mounds of timbers and pits, preserved under silt and mud.', 'teaser-card-s047-rollback:a9a32ee2-bd62-4fe4-8515-0ccdda65a7ee:card_description', 'rollback of teaser-card-s047: card_description ''In approximately 11 metres of water off the Isle of Wight lies Bouldnor Cliff, a settlement of about 8,000 years ago: burnt flints, mounds of timbers and pits, preserved under silt and mud.'' restored on Bouldnor Cliff', 'c122bb7ff1671776f2af61940713e4c957902c3fe7c754e78247081948252fc0|ed6a4ae9b41d62d211327a9ff8c66b3b626dbd1d600e1b336993c8f7fe918dff|ed6a4ae9b41d62d211327a9ff8c66b3b626dbd1d600e1b336993c8f7fe918dff', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "About 11 metres under water lies a Middle Stone Age settlement. Rising waters swamped it and covered it in silt and mud, and experts have found burnt flints, mounds of timbers and pits."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "the site lies about 11 metres under water [S1, S2]; it is a settlement [S1, S3]; it dates from the Middle Stone Age (Mesolithic) [S2]; rising waters swamped it [S4]; the waters covered it in silt and mud [S5]; experts found burnt flints [S6]; they found mounds of timbers [S6]; they found pits [S6]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "About 11 metres under water lies this settlement [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; It is a settlement [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; The settlement dates from the Middle Stone Age [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; Rising waters swamped it [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; The rising waters covered it in silt [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; The rising waters covered it in mud [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; Experts have found burnt flints [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; Experts have found mounds of timbers [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]; Experts have found pits [SUPPORTED: https://maritimearchaeologytrust.org/projects-research/bouldnor-cliff/]"}]'::jsonb),
    ('aaa12d23-d666-4a40-9f3c-17d861f4e143'::uuid, 'card_description', 'Quarry workers found these rock engravings by chance in the 1930s. The carvings include figures with lances, ritual dances, bullfights, camel caravans, and the sun and other stars.', 'Lance-bearers, ritual dances, camel caravans, the sun and other stars: quarry workers stumbled on the Gobustan Rock Art in the 1930s, engravings from prehistoric to medieval times.', 'teaser-card-s047-rollback:aaa12d23-d666-4a40-9f3c-17d861f4e143:card_description', 'rollback of teaser-card-s047: card_description ''Lance-bearers, ritual dances, camel caravans, the sun and other stars: quarry workers stumbled on the Gobustan Rock Art in the 1930s, engravings from prehistoric to medieval times.'' restored on Gobustan Rock Art', '0ad54aa412c3a524c51a204e36ee016b78a76cdc339db8c337e1ac391444ff58|9a89f46b1cf4868042882cf57d0e94e2c030c56dcaa265d91c0ac2b0b5c71f4e|9a89f46b1cf4868042882cf57d0e94e2c030c56dcaa265d91c0ac2b0b5c71f4e', '[{"source": "lane WB run wb-shorts-wave-a2-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Quarry workers found these rock engravings by chance in the 1930s. The carvings include figures with lances, ritual dances, bullfights, camel caravans, and the sun and other stars."}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "quarry workers found the rock engravings [S5]; they found them by chance [S5]; this was in the 1930s [S5]; the site consists of rock engravings [S1, S2]; the carvings include figures with lances [S2]; they include ritual dances [S2]; they include bullfights [S2]; they include camel caravans [S2]; they include the sun and other stars [S2]"}, {"source": "lane WB run wb-shorts-wave-a2-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a2-2026-10-24/OUTCOMES.jsonl", "quote": "Quarry workers found these rock engravings [SUPPORTED: https://www.azer.com/aiweb/categories/magazine/62_folder/62_articles/62_gobustan.html]; The engravings were found by chance [SUPPORTED: https://www.azer.com/aiweb/categories/magazine/62_folder/62_articles/62_gobustan.html]; The engravings were found in the 1930s [SUPPORTED: https://qobustan.jnews.az/en/petroglyphs.html]; The site''s images are rock engravings [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include figures with lances [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include ritual dances [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include bullfights [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include camel caravans [SUPPORTED: https://qobustan.jnews.az/en/petroglyphs.html]; The carvings include the sun [SUPPORTED: https://qobustan.jnews.az/en/petroglyphs.html]; The carvings include other stars [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 47;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s047-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s047-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s047-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 47 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s047-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s047-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
